-- Table structure for item_effect_base
-- ----------------------------
DROP TABLE IF EXISTS `item_effect_base`;
CREATE TABLE `item_effect_base` (
  `EffectID` int(10) NOT NULL AUTO_INCREMENT,
  `EffectType` int(1) NOT NULL DEFAULT '1' COMMENT 'Equipable Effect (0) or Activatable (1)',
  `Name` varchar(256) NOT NULL COMMENT 'Effect Name',
