  `flag1` int(10) NOT NULL DEFAULT '0' COMMENT 'Effect Flag',
  `flag2` int(10) NOT NULL DEFAULT '0' COMMENT 'Effect Flag',
  `Constant1Value` float(10,3) NOT NULL DEFAULT '0.000' COMMENT 'Constant Value',
  `Constant1Stat` varchar(50) NOT NULL DEFAULT 'NO_STAT' COMMENT 'Modifying Stat',
  `Constant1Type` int(1) NOT NULL DEFAULT '0' COMMENT '(0) Not Used (1) Inc Value (2) Dec Value (3) Inc % (4) Dec %',
  `Constant2Value` float(10,3) NOT NULL DEFAULT '0.000' COMMENT 'Constant Value',
  `Constant2Stat` varchar(50) NOT NULL DEFAULT 'NO_STAT' COMMENT 'Modifying Stat',
  `Constant2Type` int(1) NOT NULL DEFAULT '0' COMMENT '(0) Not Used (1) Inc Value (2) Dec Value (3) Inc % (4) Dec %',
  `Var1Stat` varchar(50) NOT NULL DEFAULT 'NO_STAT' COMMENT 'Modifying Stat',
  `Var1Type` int(1) NOT NULL DEFAULT '0' COMMENT '(0) Not Used (1) Inc Value (2) Dec Value (3) Inc % (4) Dec %',
  `Var2Stat` varchar(50) NOT NULL DEFAULT 'NO_STAT' COMMENT 'Modifying Stat',
  `Var2Type` int(1) NOT NULL DEFAULT '0' COMMENT '(0) Not Used (1) Inc Value (2) Dec Value (3) Inc % (4) Dec %',
  `Var3Stat` varchar(50) NOT NULL DEFAULT 'NO_STAT' COMMENT 'Modifying Stat',
  `Var3Type` int(1) NOT NULL DEFAULT '0' COMMENT '(0) Not Used (1) Inc Value (2) Dec Value (3) Inc % (4) Dec %',
  `Buff_Name` varchar(50) NOT NULL DEFAULT 'BUFF_NONE',
  `VisualEffect` int(10) NOT NULL DEFAULT '-1' COMMENT 'Visual Effects',
  `Var1_mod` float NOT NULL DEFAULT '1' COMMENT 'Modifier for Variable 1',
  `Var2_mod` float NOT NULL DEFAULT '1' COMMENT 'Modifier for Variable 2',
  `Var3_mod` float NOT NULL DEFAULT '1' COMMENT 'Modifier for Variable 3',
  `O2OEffect` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT 'type of visual effect',
  PRIMARY KEY (`EffectID`),
  KEY `Constant1Stat` (`Constant1Stat`),
  KEY `Constant2Stat` (`Constant2Stat`),
  KEY `Var1Stat` (`Var1Stat`),
  KEY `Var2Stat` (`Var2Stat`),
  KEY `Var3Stat` (`Var3Stat`),
  CONSTRAINT `item_effect_base_ibfk_1` FOREIGN KEY (`Constant1Stat`) REFERENCES `item_effect_stats` (`Stat_Name`),
  CONSTRAINT `item_effect_base_ibfk_2` FOREIGN KEY (`Constant2Stat`) REFERENCES `item_effect_stats` (`Stat_Name`),
  CONSTRAINT `item_effect_base_ibfk_3` FOREIGN KEY (`Var1Stat`) REFERENCES `item_effect_stats` (`Stat_Name`),
  CONSTRAINT `item_effect_base_ibfk_4` FOREIGN KEY (`Var2Stat`) REFERENCES `item_effect_stats` (`Stat_Name`),
  CONSTRAINT `item_effect_base_ibfk_5` FOREIGN KEY (`Var3Stat`) REFERENCES `item_effect_stats` (`Stat_Name`)
) ENGINE=InnoDB AUTO_INCREMENT=238 DEFAULT CHARSET=latin1;

