INSERT INTO `item_base` VALUES ('987', '5', '10', '100', '14', '1', 'Baron La Croix\'s Iku', 'Maria Escaler is probably the only woman to have successfullyBlackmailled Miguel Chavez. The amount she got out of him was undeclosed, but he was so impressed by her abilities, he hired her on and gave her one of his own EMP beam weapons as a gesture of good faith. She kept his money.\\n\\nBaron La Croix\'s Iku reduces the amount of damage taken to weapons, increases Beam Weapon skills and increases scanning range.', '1', '786', '339', '0', '0', '0', '1', '1', null, '0', '2', '0', '65712', '21904', '130', '28476', '50', '50', '50', '100', '85426', '6572', '130', '10', '1.1'), ('988', '5', '10', '100', '14', '1', 'Mace V', 'The Sparta Mace V will drain your target\'s energy as well as its shields. When equipped, the Sparta Mace gives increased Prospect Skill and increased Shield Regeneration. Sparta. When the Call comes, be ready. ', '4', '779', '341', '0', '0', '0', '0', '0', null, '0', '2', '0', '95915', '31972', '130', '41564', '50', '50', '50', '100', '124690', '9592', '130', '10', '1.5'), ('989', '5', '10', '100', '14', '1', 'Scimitar Prime', 'When equipped, the Sparta Scimitar gives increased Combat Trance Skill and increased Self Destruct Skill.\\nSparta! When the Call comes, be ready.', '4', '780', '777', '0', '0', '0', '0', '0', null, '0', '2', '0', '53382', '17794', '130', '23133', '50', '50', '50', '100', '69397', '5339', '130', '10', '1.5');
