INSERT INTO `item_base` VALUES ('5165', '1', '11', '110', '11', '1', 'Handy Solar Projects Manual', 'This data diskette contains information and schematics for building a multitude of different solar projects. The full title is: \"Handy Solar Projects You Can Build at Home\" by Dr. Zachariah Garrett.', '0', '1381', '1335', '1', '0', '0', '1', '0', null, '0', '2', '0', '2891', '9999999', '130', '12999999', '50', '50', '50', '100', '3759', '1157', '130', '40', '1');
