INSERT INTO `item_base` VALUES ('5260', '4', '10', '103', '10', '130', 'Plasma Rocket Type X2', 'Missile Launcher Rocket type X2 Plasma. Brother of rocket Type X1 is still frog. Rocket Type X2 using please Type X2 missile launcher with. Tada-O! Big! Strong! Wow!\\nThe Type X2 plasma missile will drain your target`s shields over a period of time.', '6', '686', '602', '0', '0', '0', '0', '0', null, '0', '2', '0', '74', '25', '10', '3', '50', '50', '50', '100', '97', '8', '130', '10', '1.3');
