INSERT INTO `item_base` VALUES ('5266', '8', '11', '110', '11', '1', 'One-Track Mind', 'Focus!  Keep yer eye on what yer doin\' an\' use this little gem to help ya!', '0', '651', '549', '0', '0', '0', '1', '0', null, '0', '2', '0', '130826', '9999999', '130', '12999999', '50', '50', '50', '100', '170074', '52331', '130', '40', '1');
INSERT INTO `item_base` VALUES ('5267', '2', '90', '-1', '13', '1', 'Reactor Waste', 'The byproduct waste the emits from a well tended reactor. It can be refined to extract certain compounds that can be used for other purposes. Ain\'t technology grand?\\n\\nThis stuff can be processed at Mercury Station, Yasuragi, or on Tokai Saikutsu.', '0', '145', '25', '0', '1', '0', '1', '0', null, '0', '2', '0', '120', '9999999', '130', '12999999', '50', '50', '50', '100', '156', '48', '130', '40', '1');
