INSERT INTO `item_base` VALUES ('5274', '7', '11', '110', '11', '1', 'Asunder Xerion Device', 'This engimatic device was given to you by 1Z1Z2L in order to aid in his research. It has been charged with the essence of the three military leaders.\\n\\n[Race Restricted\\nprofession Restricted\\nin red]', '0', '2244', '2247', '1', '1', '0', '1', '0', null, '0', '2', '0', '350468', '9999999', '130', '12999999', '50', '50', '50', '100', '455609', '140188', '130', '40', '1');
