INSERT INTO `item_base` VALUES ('6153', '5', '-1', '-1', '13', '60', 'EarthCorps Wanted Notice', '\"Wanted: Nathan Zhao. Suspected leader of the Heung tong of Red Dragon Pirates. If apprehended, bring to Neptune Detention Centre for reward. Last sited in Asteroid Belt Alpha.\" Substantial monetary reward offered by EarthCorps.', '0', '1380', '1334', '0', '0', '0', '1', '0', null, '0', '2', '0', '1624', '9999999', '130', '12999999', '50', '50', '50', '100', '2112', '650', '130', '40', '1'), ('6154', '2', '-1', '-1', '13', '60', 'Sha\'ha\'dem Scientific Report Si2', 'A confusing, oftentimes contradictory account of three months of research beyond the Intzalan Line, near the primary star of Sirius. Describes some of the unexplained effects reported by ships in this area, including temporary loss of equipment functionality, temporary reductions in in engine speed, and sudden losses of reactor energy. Effects are almost always preceded by a prickling at the back of the neck, a feeling of dread, or a sense of being observed from afar.', '0', '1381', '1335', '0', '0', '0', '1', '0', null, '0', '2', '0', '658', '9999999', '130', '12999999', '50', '50', '50', '100', '856', '264', '130', '40', '1'), ('6155', '2', '-1', '-1', '13', '60', 'Alien Artifact', 'Medium Sized, emblazoned with indecipherable runes. Slight burn marks at narrow end of the device. Label reads:\"From modara Maelstrom. Usage unkown, possibly an explosive. Handle with care.\"', '0', '733', '575', '0', '0', '0', '1', '0', null, '0', '2', '0', '657', '9999999', '130', '12999999', '50', '50', '50', '100', '855', '263', '130', '40', '1'), ('6156', '2', '-1', '-1', '13', '60', 'Centuriata Intelligence Report X-54', 'Long. complex assessment of Progen tactical position in Vega, by an un-named senior officer. Main conclusion is that Red Dragons are exploiting the excessive interest and caution of Republican forces around the the Mondara Maelstrom. Also describes evidence of the Red Dragon activity around asteroids in Tarsis and Primus sectors.', '0', '1381', '1335', '0', '0', '0', '1', '0', null, '0', '2', '0', '628', '9999999', '130', '12999999', '50', '50', '50', '100', '817', '252', '130', '40', '1'), ('6157', '9', '10', '103', '10', '1200', 'Plasma Black Casters', 'Ammo for Blackbeard\'s Personal weapon, the Black Caster. Use with caution.', '0', '713', '629', '0', '0', '0', '0', '0', null, '0', '2', '0', '400', '134', '10', '14', '50', '50', '50', '100', '520', '40', '130', '10', '1.3'), ('6158', '9', '10', '103', '10', '1200', 'Chemical Black Casters', 'Ammo for Blackbeard\'s Personal weapon, the Black Caster. Use with caution.', '0', '713', '629', '0', '0', '0', '0', '0', null, '0', '2', '0', '400', '134', '10', '14', '50', '50', '50', '100', '520', '40', '130', '10', '1.3'), ('6159', '9', '10', '103', '10', '1200', 'EMP Black Casters', 'Ammo for Blackbeard\'s Personal weapon, the Black Caster. Use with caution.', '0', '713', '629', '0', '0', '0', '0', '0', null, '0', '2', '0', '400', '134', '10', '14', '50', '50', '50', '100', '520', '40', '130', '10', '1.3'), ('6160', '7', '80', '209', '13', '60', 'Galactic Rimstone', 'Refined from: Raw Galactic Rimstone', '0', '1469', '99', '0', '0', '0', '0', '0', null, '0', '2', '0', '582', '388', '80', '311', '50', '50', '50', '100', '757', '466', '130', '80', '1'), ('6161', '7', '80', '209', '13', '60', 'Firerock', 'Refined from: Raw Firerock', '0', '1469', '99', '0', '0', '0', '0', '0', null, '0', '2', '0', '720', '480', '80', '384', '50', '50', '50', '100', '936', '576', '130', '80', '1'), ('6162', '5', '80', '209', '13', '60', 'Black Pearl', 'Refined from: Raw Black Pearl', '0', '2365', '1925', '0', '0', '0', '0', '0', null, '0', '2', '0', '2135', '1424', '80', '1140', '50', '50', '50', '100', '2776', '1708', '130', '80', '1'), ('6163', '6', '80', '209', '13', '60', 'Icy Pearl', 'Refined from: Raw Icy Pearl', '0', '1469', '99', '0', '0', '0', '0', '0', null, '0', '2', '0', '366', '244', '80', '196', '50', '50', '50', '100', 