INSERT INTO `item_base` VALUES ('6185', '5', '90', '-1', '13', '1', 'Exotic Dancers', 'Specially ordered, with impossibly perfect bodies, to help relax off-duty Progen troops. Version III of the order, not Version II which tended to suddenly turn hostile and tried to \"Bobitt\" the troops or Version I which exploded.\\nSafe!\\n\\n\\nEspecially welcome in Nostrand Vor!', '0', '205', '36', '0', '1', '0', '1', '0', null, '0', '2', '0', '1507', null, null, null, null, null, null, null, null, null, null, null, null), ('6186', '4', '90', '-1', '13', '1', 'Weapons Grade Discordite', 'Prepackaged, stabilized weapons grade Discordite. The packaging will detonate if you try and open them. Unstable in wormholes or if hull carrying it is breached.\\nSafe Travels!\\n\\nNostrand Vor has orders to be filled for this item.', '0', '1286', '69', '0', '1', '0', '1', '0', null, '0', '2', '0', '960', null, null, null, null, null, null, null, null, null, null, null, null), ('6187', '3', '90', '-1', '13', '1', 'Orsini Mining Corp Ore Request Order XXVIC', 'This is an order for 1 unit of Weapons Grade Discordite to be sent to Norstrand Vor.\\n\\nThis is to be taken to Orsini Mining Station.', '0', '1381', '1335', '0', '1', '0', '1', '0', null, '0', '2', '0', '285', null, null, null, null, null, null, null, null, null, null, null, null), ('6188', '5', '90', '-1', '13', '1', 'Terran Alliance Prisoner of War', 'Captured by the Progen Combine in 61 Cygni, this prisoner is being transported from Pax Remar to Earth Station to facilitate a prisoner of war exchange. Warning! Carrying this Prisoner of War may attract a rescue by their own side.', '0', '205', '36', '0', '1', '0', '1', '0', null, '0', '2', '0', '1657', null, null, null, null, null, null, null, null, null, null, null, null), ('6189', '5', '90', '-1', '13', '1', 'Progen Combine Prisoner of War', 'Captured by the Terran Alliance in 61 Cygni, this prisoner is being transported from ECS Bremen to Arx Magister to facilitate a prisoner exchange. Warning! Carrying this Prisoner of War may attract a rescue by their own side.', '0', '196', '35', '0', '1', '0', '1', '0', null, '0', '2', '0', '1657', null, null, null, null, null, null, null, null, null, null, null, null), ('6190', '2', '90', '-1', '13', '1', 'Progen Raw Recruits', 'Soldiers, fresh out of the vats, for the front lines. New itterations for the Progen Republic.\\n\\n\\nArx Emporos is impatiently awaiting these recruits. ', '0', '205', '36', '0', '1', '0', '1', '0', null, '0', '2', '0', '154', null, null, null, null, null, null, null, null, null, null, null, null), ('6191', '2', '90', '-1', '13', '1', 'Prisoners', 'Detainees and other lowlifes to be transported to Detention Center Ororom.', '0', '206', '37', '0', '1', '0', '1', '0', null, '0', '2', '0', '145', null, null, null, null, null, null, null, null, null, null, null, null), ('6192', '3', '90', '-1', '13', '1', 'Encrypted Intelligence Reports', 'CLASSIFIED!  You should not be reading this. Augustus Var has now been informed.\\n\\n\\nThese reports are to be taken to Arx Tiberius.\\n\\n', '0', '1381', '1335', '0', '1', '0', '1', '0', null, '0', '2', '0', '412', null, null, null, null, null, null, null, null, null, null, null, null), ('6193', '1', '90', '-1', '13', '1', '61 Cygni Progen Battle Reports', 'REQUEST: For more troops.  Terrans have been held along the line. What is the Signifer on Arx Magister doing?\\nWhy have Net-7 not started to recruit mercenaries? The Progen Combine are requesting moe aid. \"Send reinforcements now.\"\\n\\nPlease take this request to Arx Magister, Quickly!', '0', '1381', '1335', '0', '1', '0', '1', '0', null, '0', '2', '0', '68', null, null, null, null, null, null, null, null, null, null, null, null), ('6194', '9', '-1', '-1', '13', '1', 'Blinding Plume', 'A Blinding Voltoi  plume.', '0', '1368', '1322', '0', '0', '0', '1', '0', null, '0', '2', '0', '2891', null, null, null, null, null, null, null, null, null, null, null, null);
