INSERT INTO `missions` VALUES ('359', '<Mission ID=\"359\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: FIGHT MOB </Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks: FIGHT MOB (Level 4 ScuttleBug Hatchling)</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">61</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion FIGHT MOB 1?</Text>\r\n<Branch Node=\"2\">I am here to check FIGHT MOB </Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion FIGHT MOB</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that FIGHT MOB works.  (Level 4 ScuttleBug Hatchling)</Description>\r\n<Completion ID=\"4\" Count=\"1\">1257</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to PHILLIPE  to postpone mission.</Description>\r\n<Completion ID=\"1\">61</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then FIGHT MOB works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: FIGHT MOB ', '61', '0', '30'), ('360', '<Mission ID=\"360\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: GIVE CREDITS 1 </Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks: GIVE CREDITS 1 </Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">62</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion GIVE CREDITS 1 ?</Text>\r\n<Branch Node=\"2\">I am here to check GIVE CREDITS 1  </Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion GIVE CREDITS 1 </Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that GIVE CREDITS 1  works.  (pay 1 credit)</Description>\r\n<Completion ID=\"14\">1</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to IKOSEI SATO  to postpone mission.</Description>\r\n<Completion ID=\"1\">62</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then GIVE CREDITS 1  works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: GIVE CREDITS 1 ', '341', '0', '30'), ('361', '<Mission ID=\"361\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: NAV MESSAGE</Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks: NAV MESSAGE (Net 7 Sol Beacon)</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">63</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion NAV MESSAGE?</Text>\r\n<Branch Node=\"2\">I am here to check NAV MESSAGE</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion NAV MESSAGE</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that NAV MESSAGE works.  Net 7 Sol Beacon</Description>\r\n<Completion ID=\"17\" Count=\"30000\">38</Completion>\r\n<Tree Node=\"1\">\r\n<Text>THIS IS A NAV MESSAGE!!!</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to SHELTON SMOOT to postpone mission.</Description>\r\n<Completion ID=\"1\">63</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then NAV MESSAGE works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: NAV MESSAGE', '341', '0', '30');
INSERT INTO `missions` VALUES ('362', '<Mission ID=\"362\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: GIVE ITEM (Net 7 Daily News Updates) </Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks:GIVE ITEM   </Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">55</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion GIVE ITEM   ?</Text>\r\n<Branch Node=\"2\">I am here to check GIVE ITEM   </Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion GIVE ITEM  </Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that GIVE ITEM  works.  )</Description>\r\n<Completion ID=\"2\" Count=\"1\">5256</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to HERCULES GRAVEL  to postpone mission.</Description>\r\n<Completion ID=\"1\">55</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then GIVE ITEM    works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: GIVE ITEM (Net 7 Daily News Updates) ', '341', '0', '30');
INSERT INTO `missions` VALUES ('363', '<Mission ID=\"363\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: NEAREST NAV</Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks: NEAREST NAV - Net 7 Sol Beacon</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">53</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion NEAREST NAV?</Text>\r\n<Branch Node=\"2\">I am here to check NEAREST NAV</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion NEAREST NAV</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that NEAREST NAV works.  Net 7 Sol Beacon</Description>\r\n<Completion ID=\"6\">38</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to ZONA MASON  to postpone mission.</Description>\r\n<Completion ID=\"1\">53</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage thenNEAREST NAV works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: NEAREST NAV', '53', '0', '30');
INSERT INTO `missions` VALUES ('364', '<Mission ID=\"364\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: OBTAIN ITEM (Net 7 Daily News Updates) </Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks:OBTAIN ITEM    </Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">54</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion OBTAIN ITEM    ?</Text>\r\n<Branch Node=\"2\">I am here to check OBTAIN ITEM    </Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion OBTAIN ITEM    </Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that OBTAIN ITEM   works. </Description>\r\n<Completion ID=\"8\">5256</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to VIP HARDY  to postpone mission.</Description>\r\n<Completion ID=\"1\">54</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then OBTAIN ITEM     works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: OBTAIN ITEM (Net 7 Daily News Updates) ', '341', '0', '30');
