INSERT INTO `missions` VALUES ('366', '<Mission ID=\"366\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: PROXIMETRY TO SPACE NPC</Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks: PROXIMETRY TO SPACE NPC (Net 7 Sol Beacon)</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">61</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion PROXIMETRY TO SPACE NPC?</Text>\r\n<Branch Node=\"2\">I am here to check PROXIMETRY TO SPACE NPC</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion PROXIMETRY TO SPACE NPC</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that PROXIMETRY TO SPACE NPC works.  Net 7 Sol Beacon</Description>\r\n<Completion ID=\"18\">38</Completion>\r\n<Tree Node=\"1\">\r\n<Text>THIS IS A PROXIMETRY TO SPACE NPC MESSAGE!!!</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to PHILLIPE to postpone mission.</Description>\r\n<Completion ID=\"1\">61</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then PROXIMETRY TO SPACE NPC works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: PROXIMETRY TO SPACE NPC', '341', '0', '30');
INSERT INTO `missions` VALUES ('367', '<Mission ID=\"367\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: RECEIVE ITEM 1 </Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks: RECEIVE ITEM  1 - This may not yet be implemented</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">62</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion RECEIVE ITEM    ?</Text>\r\n<Branch Node=\"2\">I am here to check RECEIVE ITEM    </Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion RECEIVE ITEM    </Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that RECEIVE ITEM 1  works. </Description>\r\n<Completion ID=\"3\">1</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to IKOSEI SATO  to postpone mission.</Description>\r\n<Completion ID=\"1\">62</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then RECEIVE ITEM     works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: RECEIVE ITEM 1 ', '341', '0', '30'), ('368', '<Mission ID=\"368\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: TALK TO SPACE NPC</Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks: TALK TO SPACE NPC (Net 7 Sol Beacon)</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">63</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion TALK TO SPACE NPC?</Text>\r\n<Branch Node=\"2\">I am here to check TALK TO SPACE NPC</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion TALK TO SPACE NPC</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that TALK TO SPACE NPC works.  Net 7 Sol Beacon</Description>\r\n<Completion ID=\"19\">38</Completion>\r\n<Tree Node=\"1\">\r\n<Text>THIS IS A TALK TO SPACE NPC MESSAGE!!!</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to SHELTON SMOOT to postpone mission.</Description>\r\n<Completion ID=\"1\">63</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then TALK TO SPACE NPC works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: TALK TO SPACE NPC', '341', '0', '30'), ('369', '<Mission ID=\"369\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: USE SKILL ON MOB (MENACE)</Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks:  USE SKILL ON MOB (MENACE) (Level 4 ScuttleBug Hatchling)</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">53</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion  USE SKILL ON MOB </Text>\r\n<Branch Node=\"2\">I am here to check  USE SKILL ON MOB</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion  USE SKILL ON MOB</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that  USE SKILL ON MOB works. (MENACE) (Level 4 ScuttleBug Hatchling)</Description>\r\n<Completion ID=\"10\" Data=\"33\">1257</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to ZONA MASON  to postpone mission.</Description>\r\n<Completion ID=\"1\">53</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then  USE SKILL ON MOB works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: USE SKILL ON MOB (MENACE)', '53', '0', '30');
INSERT INTO `missions` VALUES ('370', '<Mission ID=\"370\" forfeitable=\"1\" time=\"0\">\r\n<Name>Check a completion: USE SKILL ON OBJECT (MENACE)</Name>\r\n<Summary>Mission for Beta and above to check a single completion.  If this mission fails report it to a developer.  This mission checks:  USE SKILL ON OBJECT (MENACE) (Net 7 Sol Beacon)</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">54</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you are here to check the completion  USE SKILL ON OBJECT </Text>\r\n<Branch Node=\"2\">I am here to check  USE SKILL ON OBJECT </Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok lets check the completion  USE SKILL ON OBJECT </Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Check that  USE SKILL ON OBJECT  works. (MENACE) (Net7 Sol! Beacon)</Description>\r\n<Completion ID=\"11\" Data=\"33\">38</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Go back to VIP HARDY  to postpone mission.</Description>\r\n<Completion ID=\"1\">54</Completion>\r\n<Tree Node=\"1\">\r\n<Text>If you see this stage then  USE SKILL ON OBJECT  works.</Text>\r\n<Branch Node=\"2\">Great</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am postponing this mission so you can try it again</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Check a completion: USE SKILL ON OBJECT (MENACE)', '53', '0', '30');
INSERT INTO `missions` VALUES ('371', '<Mission ID=\"371\" forfeitable=\"1\" time=\"0\">\r\n<Name>Ammunition Resupply [Version 1.1.P]</Name>\r\n<Summary>Supply the Capital Contruction Ship around Arx Bursa with enough ammunition to withstand further Critter Swarm attacks.</Summary>\r\n<Condition ID=\"10\">276</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"18\">12318</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hail @name.\r\nThat was a timely intervention of destroying those suicidal critters!  I was half wondering if I had to call in a favour to destroy them!</Text>\r\n<Branch Node=\"2\">Ok, what do you need?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok, here\'s what we need:\r\n5 Stacks of Rifle Ammunition (Plasma)\r\n5 Stacks of Rifle Ammunition (Chemical)\r\n\r\n\r\nRifle ammuinition is the mainstay of the Progen Fleet.  More modern ammunition is out there, Mortars are in development and also the much sought after Archos.  However, once you reach the use of Rifles, you will be a serious contender out there.\r\n</Text>\r\n<Branch Node=\"3\">Can\'t you use Blowgun, Musket or Crossbow Ammunition?</Branch>\r\n<Branch Node=\"4\">I can\'t get you Rifle Ammunition.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Level 2 ammunition doesn\'t fit my guns!\r\n\r\nI know it is a bit much, you may have to return to me another time to get the required ammunition. I insist on the best, are you the one to supply it to me?</Text>\r\n<Branch Node=\"4\">I\'m not advanced enough to do this.</Branch>\r\n<Branch Node=\"5\">I\'ll get you the ammunition!</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>That\'s ok, your probably too unexperienced to deliver the goods.\r\nContact me again when you are ready to supply me with the ammunition!</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>That\'s the spirit.\r\nI\'ll be waiting for the ammunition supply.  Who knows, if successful you may even get the contract to resupply the Fleet in 61 Cygni.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Obtain 5 stacks of Rifle Plasma Ammunition.  \r\n[Doesn\'t Check for mor than 1 but you need the full amount to complete mission]\r\n[Eventually this will be made by yourself only]</Description>\r\n<Completion ID=\"8\">608</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Obtain 5 stacks of Rifle Chemical Ammunition \r\n[Doesn\'t Check for mor than 1 but you need the full amount to complete mission]\r\n[Eventually this will be made by yourself only]</Description>\r\n<Completion ID=\"8\">607</Completion>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Resupply the Capital Construction Ship around Arx Bursa with 5 stacks of Rifle Plasma Ammunition and 5 stacks of Rifle Chemical Ammunition.</Description>\r\n<Completion ID=\"19\">12318</Completion>\r\n<Completion ID=\"13\" Count=\"3000\">608</Completion>\r\n<Completion ID=\"13\" Count=\"3000\">607</Completion>\r\n<Completion ID=\"2\" Count=\"500\">607</Completion>\r\n<Completion ID=\"2\" Count=\"500\">607</Completion>\r\n<Completion ID=\"2\" Count=\"500\">607</Completion>\r\n<Completion ID=\"2\" Count=\"500\">607</Completion>\r\n<Completion ID=\"2\" Count=\"500\">607</Completion>\r\n<Completion ID=\"2\" Count=\"500\">607</Completion>\r\n<Completion ID=\"2\" Count=\"500\">608</Completion>\r\n<Completion ID=\"2\" Count=\"500\">608</Completion>\r\n<Completion ID=\"2\" Count=\"500\">608</Completion>\r\n<Completion ID=\"2\" Count=\"500\">608</Completion>\r\n<Completion ID=\"2\" Count=\"500\">608</Completion>\r\n<Completion ID=\"2\" Count=\"500\">608</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Well @name, that\'s what I like to see.\r\nRifle ammunition.</Text>\r\n<Branch Node=\"2\">I live to serve.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>This will protect this station against the critter swarm.\r\nWell done, @profession.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"4\">25000</Reward>\r\n<Reward ID=\"5\" Flags=\"5\">2000</Reward>\r\n<Reward ID=\"1\">20000</Reward>\r\n<Reward ID=\"2\">10000</Reward>\r\n<Reward ID=\"3\">10000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Ammunition Resupply [Version 1.1.P]', '101', '0', '30');
INSERT INTO `missions` VALUES ('372', '<Mission ID=\"372\" forfeitable=\"1\" time=\"0\">\r\n<Name>Talk to Merjan Kathrada</Name>\r\n<Summary>Merjan Kathrada is the leader of the Sha\'ha\'dem Explorers. It would be wise to get to know her.</Summary>\r\n<Condition ID=\"10\">138</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">83</Completion>\r\n<Tree Node=\"1\">\r\n<Text>It\'s now time for you to meet your leader, the leader of all Sha\'ha\'dem, Merjan Kathrada. She comes off a bit strong, but she will be your new teacher. You can learn much from her.</Text>\r\n<Branch Node=\"2\">Ok, thank you for your teaching.</Branch>\r\n<Branch Node=\"3\">But I\'m having tea with DeWinter this afternoon.. That won\'t do.</Branch>\r\n<Branch Node=\"4\">She doesn\'t deserve to be in my presense.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>You are very welcome, @name. Proceed to Kailaasa, Capella and meet your new teacher.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Very well then. Finish your existing appointment and return to me. And tell her I said hello.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>You disgrace me with your insults of our leader. Merjan is a great woman who has had a difficult life yet always seems to lead us to success. Treasure her knowledge, for she is one of our wisest and most experienced.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Seek out the Sha\'ha\'dem leader, Merjan Kathrada at Paren Station in Kailaasa (Capella System).</Description>\r\n<Completion ID=\"1\">363</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Greetings Truth Seeker. I have expected you. Both Kalas Ben Joseph and Shin-Tzu Li look upon you favorably, which is a feat.</Text>\r\n<Branch Node=\"2\">They have been excellent teachers.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am sure of it. Now you are here for many reasons. To learn about me, to learn about that strange object, and to serve the Sha\'ha\'dem.</Text>\r\n<Branch Node=\"3\">Who are you?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>I am Merjan Kathrada, leader, teacher and explorer of the Sha\'ha\'dem. I have led explorations into the most dangerous areas of uncharted space, and it is my goal to discover the secrets of the universe. There are many things we still do not know, and it is my goal to uncover as many of these secrets as I can.\r\n\r\nIt is nice to meet you, @name.</Text>\r\n<Branch Node=\"4\">So what should I do now?</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>So I heard you found what Shin-Tzu Li believes to be an ancient fragment. Ask him for that object back so you can bring it to Ayako Ravenlock, the Jenquai archaeologist who resides in this station. She is an expert with ancient technology who could hopefully unpuzzle this artifact.</Text>\r\n<Branch Node=\"5\">Ok. And you had a request?</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>It is up to you, Sha\'ha\'dem. If you would like to help the Jenquai, let me know. There would be a great deal in it for both of us.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"2\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Talk to Merjan Kathrada', '83', '0', '0'), ('373', '<Mission ID=\"373\" forfeitable=\"1\" time=\"0\">\r\n<Name>Temp TT Build Shields Mission</Name>\r\n<Summary>Delete when 61 Cygni opens.</Summary>\r\n<Condition ID=\"5\">0</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">315</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hey. I will teach you build shields.</Text>\r\n<Branch Node=\"2\">Ok.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Show me the money!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Talk to Jurgen again.</Description>\r\n<Completion ID=\"1\">315</Completion>\r\n<Tree Node=\"1\">\r\n<Text>There we go.</Text>\r\n<Branch Node=\"2\">Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Enjoy.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"9\">9</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Temp TT Build Shields Mission', '315', '0', '0');
INSERT INTO `missions` VALUES ('374', '<Mission ID=\"374\" forfeitable=\"1\" time=\"0\">\r\n<Name>Hull Level 135 Mission Reminder  [Version 1.1.-]</Name>\r\n<Summary>At level 135 contact Gratis Augustus Var at Arx Tiberius (Tarsis).  </Summary>\r\n<Condition ID=\"7\">5</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Condition ID=\"1\">135</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"18\">96</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Gratis Augustus Var the commander of Arx Tiberius in Tarsis has a mission that will provide you with a reward of a hull upgrade.  Should you want to pay for the hull upgrade instead, you will need 1,000,000 credits, and speak to ProConsul Kerr.\r\n\r\nIf you pay for the hull upgrade you will never be able to do the mission.  And any bonus missions or items that rely on this mission will not be awarded to you.\r\n</Text>\r\n<Branch Node=\"2\">I am on my way.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>@name.\r\nThis reminder will not happen again.</Text>\r\n<Flags>3</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Hull Level 135 Mission Reminder  [Version 1.1.-]', '100', '0', '80');
INSERT INTO `missions` VALUES ('375', '<Mission ID=\"375\" forfeitable=\"1\" time=\"0\">\r\n<Name>Hull Level 100 Mission Reminder  [Version 1.1.-]</Name>\r\n<Summary>At level 100 contact Reclaimer Nayol Wat at Arx Magister (Mars).  </Summary>\r\n<Condition ID=\"7\">4</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Condition ID=\"1\">100</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"18\">96</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Buy a drink for Reclaimer Nayol Wat in Arx Magister and obtain a mission that will provide you with a reward of a hull upgrade.  Should you want to pay for the hull upgrade instead and have 300,000 credits, speak to ProConsul Kerr.\r\n\r\nIf you pay for the hull upgrade you will never be able to do the mission.  And any bonus missions or items that rely on this mission will not be awarded to you.\r\n</Text>\r\n<Branch Node=\"2\">I am on my way.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>@name.\r\nThis reminder will not happen again.</Text>\r\n<Flags>3</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Hull Level 100 Mission Reminder  [Version 1.1.-]', '100', '0', '80');
INSERT INTO `missions` VALUES ('376', '<Mission ID=\"376\" forfeitable=\"1\" time=\"0\">\r\n<Name>Gettn\' sum guano   [Version 1.3.W+P]</Name>\r\n<Summary>Contact James Tucker in Nostrand Vor City about obtaining 15 units of Phosphates.  This mission is repeatable.</Summary>\r\n<Condition ID=\"5\">2</Condition>\r\n<Condition ID=\"1\">50</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"6\">0</Condition>\r\n<Condition ID=\"7\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"14\">10000</Completion>\r\n<Completion ID=\"1\">483</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Well \'ello yer young @proffession, wot canna I do fer yer t\' day?\r\n\r\nDer 10,000 credits woz to make sure yer don\'t run off, yer will get \'em back if yer do wot I say.  If not dem are fer me to use to pay others.\r\n</Text>\r\n<Branch Node=\"2\">I\'m called @name and I understand you can get me some Phosphates</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Tzzzk, well @name, \r\n\r\nI\'m \'oldin sum fer a gud friend, she\'s falln outta favour wid Vinda.  Trouble iz I don\'t know wen shes gonna turn up if yer gets my drift.  T\' phosphates are gunna cost yer a bit of yer time.</Text>\r\n<Branch Node=\"3\">Thats ok, at least I don\'t have to wait for a Miner!</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Miners \'re vital fer the economy, @name, my quarrel aint wid dem, but wiv Vinda on t\' warpath over my friend, I canna take any chances at t\' moment.\r\n\r\nI need yer t\' go to Friendship 7, collect six Exotic Dancers n\' then wait fer my transmission t\' tell yer where ey go.  Are yer interested in this mission?</Text>\r\n<Branch Node=\"4\">Yes</Branch>\r\n<Branch Node=\"5\">No</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>That\'s the sipirit!</Text>\r\n<Branch Node=\"7\">I\'m on my way.</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>A pity, a real pity.\r\nYou\'ve made yer own mind up n\' I\'ll not be giving you a second chance.  Enjoy tryin\' to find yer Phosphates on t\' market channel.</Text>\r\n<Branch Node=\"4\">Wait, I\'ve changed my mind, I will do your mission.</Branch>\r\n<Branch Node=\"6\">You can stuff yer mission, I\'m not crossing Vinda!</Branch>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n<Text>Goodbye.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"7\">\r\n<Text>Well whattcha know,  @name.  \'ere woz I thinking yer noggle woz wid der clouds.  Ok, get yer engines fired up and head off to Friendship 7!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Obtain six Exotic Dancers from Friendship 7, and obtain further information from the seller there.</Description>\r\n<Completion ID=\"8\">6185</Completion>\r\n<Completion ID=\"1\">217</Completion>\r\n<Tree Node=\"1\">\r\n<Text>You will take good care of the type III exotic dancers, won\'t you @name?\r\nDon\'t worry, these have been vetted against any Terran Alliance influcences!</Text>\r\n<Branch Node=\"2\">Terran Allaince?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Yes,\r\n\r\nIt appears the Terran Alliance were using the earlier versions as means to assassinate Progen Combine troops to restrict supply to Moto in 61 Cygni.\r\n\r\nJames Tucker has specially ordered these Exotic Dancers, they have been modified.\r\n</Text>\r\n<Branch Node=\"3\">Specially Modified?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Ask no questions.  One of his old comrades lost a mate in an earlier supply, and I believe this is revenge.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Give one \'present\' to Moire Archer (Sommerled Station)</Description>\r\n<Completion ID=\"2\" Count=\"1\">6185</Completion>\r\n<Completion ID=\"1\">302</Completion>\r\n<Tree Node=\"1\">\r\n<Text>[To Add Talk Tree ]\r\n</Text>\r\n<Branch Node=\"2\">Heres your Exotic Dancer you ordered!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>This is not mine.  Hang on, the package is active!\r\n\r\nGuards! Guards!\r\n\r\nAn intruder.  Stop the @race.  Yes shoot @name!\r\n</Text>\r\n<Flags Data=\"3\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Give one \'present\' to Julie Bristol (Earth Staion)</Description>\r\n<Completion ID=\"2\" Count=\"1\">6185</Completion>\r\n<Completion ID=\"1\">28</Completion>\r\n<Tree Node=\"1\">\r\n<Text>[To Add Talk Tree ]\r\n</Text>\r\n<Branch Node=\"2\">Heres your Exotic Dancer you ordered!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>This is not mine.  Hang on, the package is active!\r\n\r\nGuards! Guards!\r\n\r\nAn intruder.  Stop the @race.  Yes shoot @name!\r\n</Text>\r\n<Flags Data=\"4\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>Give one \'present\' to  Liam O\'Faden (Fenris Prime)</Description>\r\n<Completion ID=\"2\" Count=\"1\">6185</Completion>\r\n<Completion ID=\"1\">110</Completion>\r\n<Tree Node=\"1\">\r\n<Text>[To Add Talk Tree ]\r\n</Text>\r\n<Branch Node=\"2\">Heres your Exotic Dancer you ordered!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>This is not mine.  Hang on, the package is active!\r\n\r\nGuards! Guards!\r\n\r\nAn intruder.  Stop the @race.  Yes shoot @name!\r\n</Text>\r\n<Flags Data=\"5\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"5\">\r\n<Description>Give one \'present\' to General Otto vonHolden-Bismark (Margesi Station)</Description>\r\n<Completion ID=\"2\" Count=\"1\">6185</Completion>\r\n<Completion ID=\"1\">461</Completion>\r\n<Tree Node=\"1\">\r\n<Text>[To Add Talk Tree ]\r\n</Text>\r\n<Branch Node=\"2\">Heres your Exotic Dancer you ordered!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>This is not mine.  Hang on, the package is active!\r\n\r\nGuards! Guards!\r\n\r\nAn intruder.  Stop the @race.  Yes shoot @name!\r\n</Text>\r\n<Flags Data=\"6\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"6\">\r\n<Description>Give one \'present\' to Alexia Richer (EarthCorps High Command)</Description>\r\n<Completion ID=\"2\" Count=\"1\">6185</Completion>\r\n<Completion ID=\"1\">192</Completion>\r\n<Tree Node=\"1\">\r\n<Text>[To Add Talk Tree ]\r\n</Text>\r\n<Branch Node=\"2\">Heres your Exotic Dancer you ordered!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>This is not mine.  Hang on, the package is active!\r\n\r\nGuards! Guards!\r\n\r\nAn intruder.  Stop the @race.  Yes shoot @name!\r\n</Text>\r\n<Flags Data=\"7\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"7\">\r\n<Description>Give one \'present\' to Vinda (Pourvenir Mons)</Description>\r\n<Completion ID=\"2\" Count=\"1\">6185</Completion>\r\n<Completion ID=\"1\">282</Completion>\r\n<Tree Node=\"1\">\r\n<Text>What do you want, @profession, don\'t you know I am busy?\r\n\r\n</Text>\r\n<Branch Node=\"2\">Heres your Exotic Dancer you ordered!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>This is not mine.  Hang on, the package is active!\r\n\r\nGuards! Guards!\r\n\r\nAn intruder.  Stop the @race.  Yes shoot @name!\r\n</Text>\r\n<Flags Data=\"8\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"8\">\r\n<Description>Return to James Tucker (Nostrand Vor) for a start to getting your rewards.</Description>\r\n<Completion ID=\"1\">483</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Aha, my agent returns!\r\nSo what happened, @race.</Text>\r\n<Branch Node=\"2\">Everone was suspicious about the dancers!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ha!\r\nThat\'d worry \'em.  They\'ll be wantin\' t\' sweep the entire station fer security breaches.  Amazing whattya canna do wid harmless cargo!  Wastin\' valuable time if yer know wotta I mean!  </Text>\r\n<Branch Node=\"3\">Yes, I kind of do.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Don\'t be flippant with me, @name.\r\nHere\'s yer reward. \r\n\r\nIf you want more, contact Intuneric Vigoare but beware, Vinda\'s agents have just docked!</Text>\r\n<Flags Data=\"9\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"9\">\r\n<Description>Go and speak to Intuneric Vigoare to get 15 more!</Description>\r\n<Completion ID=\"1\">584</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hello @name, Tucker has asked me to ask you give you these 15 units of Phosphates.  Return to him afterwards.\r\n\r\nWe are doing it this way to stop moving a lot of Phosphates, Vinda\'s agents would inform on us!\r\n\r\n\r\n</Text>\r\n<Branch Node=\"2\">Ok.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I feel this is going to be a long day!</Text>\r\n<Flags Data=\"10\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"10\">\r\n<Description>Return to James Tucker for more.  </Description>\r\n<Completion ID=\"1\">483</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here are your next 15 phosphates. \r\nBe careful with them.  No.  Don\'t have them in plain sight!</Text>\r\n<Branch Node=\"2\">Quick pass me that Jenquai skull, it is flimsy enough to contain them!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Don\'t spell them!</Text>\r\n<Flags Data=\"11\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"11\">\r\n<Description>Return to Intuneric Vigoare to obtain more.</Description>\r\n<Completion ID=\"1\">584</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here are your next 15 phosphates.\r\nQuick, hide.  Take cover.\r\n</Text>\r\n<Branch Node=\"2\">Where!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Oh sorry, it was just a Cleaning Bot!\r\n\r\nHa ha ha, you should have seen you run!</Text>\r\n<Flags Data=\"12\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"12\">\r\n<Description>Return to James Tucker to obtain more.</Description>\r\n<Completion ID=\"1\">483</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here are your next 15 phosphates.\r\nDo you think that Sentinel over there is one of her agents?</Text>\r\n<Branch Node=\"2\">Bit too weedy looking for one of her agents.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Yes, I think your right.</Text>\r\n<Flags Data=\"13\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"13\">\r\n<Description>Return to Intuneric Vigoare to obtain more.</Description>\r\n<Completion ID=\"1\">584</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here are your next 15 phosphates.\r\nI\'m getting bored of this!</Text>\r\n<Branch Node=\"2\">You\'re getting bored, what about me!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Less of your lip!</Text>\r\n<Flags Data=\"14\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"14\">\r\n<Description>Return to James Tucker to obtain more.</Description>\r\n<Completion ID=\"1\">483</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here are your next 15 phosphates.\r\n\r\nYes, my stall is popular today!</Text>\r\n<Branch Node=\"2\">But its\' just me doing this!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>All advertising is good, @name.</Text>\r\n<Flags Data=\"15\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"15\">\r\n<Description>Return to Intuneric Vigoare to obtain more.</Description>\r\n<Completion ID=\"1\">584</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here are your next 15 phosphates.\r\nHow many do you now have?</Text>\r\n<Branch Node=\"2\">Must have about 105 units.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Looks like just three more transactions then!</Text>\r\n<Flags Data=\"16\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"16\">\r\n<Description>Return to James Tucker to obtain more</Description>\r\n<Completion ID=\"1\">483</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here are your next 15 phosphates.\r\nLet Intuneric know that I\'ll owe her one.</Text>\r\n<Branch Node=\"2\">Will do, what would she want you think?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I don\'t know about you, but I\'e got a feeling it\'ll involve the deep desert.</Text>\r\n<Flags Data=\"17\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n</Stage>\r\n<Stage ID=\"17\">\r\n<Description>Return to Intuneric Vigoare to obtain more and complete the mission!</Description>\r\n<Completion ID=\"1\">584</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here are your final 15 phosphates.\r\nNow what do you want?</Text>\r\n<Branch Node=\"2\">Tucker says he owes you one.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ah, he wants to help does he?\r\nWell, so will you later on too.  But you will have to get a little harder first.  I\'ve got a Scientific Expedition to do in the Deep Desert.  Investigating the worms.\r\n\r\n\r\nHere is your 10,000 credits you provided as insurance at the start of the mission!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"6\">2878</Reward>\r\n<Reward ID=\"1\">10000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Gettn\' sum guano   [Version 1.3.W+P]', '483', '0', '0');
INSERT INTO `missions` VALUES ('377', '<Mission ID=\"377\" forfeitable=\"1\" time=\"0\">\r\n<Name>Trade Blockade [Version 3.0.-]  </Name>\r\n<Summary>We need to expand the Collegia trade routes.  I want you to limit InfinitiCorp\'s reach.  Go kill some InfinitiCorp Bruisers.</Summary>\r\n<Condition ID=\"10\">316</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Condition ID=\"2\">20</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">473</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nOur Collegia still need to break past the InfinitiCorp trade blocks.  Can you, @name irritateTerrans to redeploy key forces from their main fleet, by removing some of their assets in 61 Cygni?\r\n\r\n</Text>\r\n<Branch Node=\"2\">Which assets?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Eliminate 10 InfinitiCorp Bruisers and 5 InfinitiCorp Paladins.  \r\n\r\nI realise this is going to be a tough act, but we will reward you for this action.\r\n\r\n</Text>\r\n<Branch Node=\"3\">For the Collegia!</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>@name.\r\n\r\nThe war is heading to stalemate in 61 Cygni.  By doing this, we should be able to reduce some of their reinforcements.  If you havn\'t already done so, go to the Net-7 beacon to sign up.\r\n\r\n\r\nThe side that you choose is up to you.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Terminate with Extreme Prejudice 10 InfinitiCorp Bruiser</Description>\r\n<Completion ID=\"4\" Count=\"10\">677</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Exterminate 5 InfinitiCorp Paladins.</Description>\r\n<Completion ID=\"4\" Count=\"5\">692</Completion>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Return to Gratis Augustus Var (Arx Tiberius in Tarsis) for a reward, even though killing InfinitiCorp and EarthCorp is reward enough.</Description>\r\n<Completion ID=\"1\">473</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@name.\r\n\r\nWell done - but so far no response has been seen.  Can you do it again?  You will not get the end reward for this until you complete it.\r\n</Text>\r\n<Branch Node=\"2\">I live for this!  Yes!</Branch>\r\n<Branch Node=\"3\">No, I\'ll take my reward now</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>@class.\r\nThats\' what I thought,\r\n\r\nThe Collegia are rewarding you with some experience and credits.  However, the greatest pleasure will be becoming a thorn in De Winters side.  Talk to me again to reselect this mission.\r\n\r\n</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>@name.\r\nSlightly dissapointed in your reply.\r\n\r\nThe Collegia are rewarding you with some experience and credits.  However, the greatest pleasure will be becoming a thorn in De Winters side.  </Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"2\">20000</Reward>\r\n<Reward ID=\"4\">20000</Reward>\r\n<Reward ID=\"3\">20000</Reward>\r\n<Reward ID=\"1\">20000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Trade Blockade [Version 3.0.-]  ', '100', '0', '0');
INSERT INTO `missions` VALUES ('378', '<Mission ID=\"378\" forfeitable=\"1\" time=\"0\">\r\n<Name>Wierd Science [Version 1.0.S]</Name>\r\n<Summary>You have been selected from many Sabine in order to train in the Call Forward Skill.\r\nWarning:  The skill may not work!</Summary>\r\n<Condition ID=\"6\">2</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Condition ID=\"1\">135</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"18\">1573</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Attention:\r\nYou have been selected to take part in training to learn the unique skill \'Call Forward\'.  Head over to Essence Research Laboratory on Arduinne Planet in order to start the mission.</Text>\r\n<Branch Node=\"2\">I\'m on my way.</Branch>\r\n<Branch Node=\"3\">I cannot do it at this moment.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>The scientist assigned to you is called Annia Severa.  She is expecting you now.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Your loss.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Go and visit the Essence Research Laboratory (Arduinne Planet), in order to help us improve the Progen Gene.</Description>\r\n<Completion ID=\"5\">4095</Completion>\r\n<Completion ID=\"19\">1267</Completion>\r\n<Completion ID=\"21\">1</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Well, if it isn\'t one of the brave progen genebank here to learn Call Forward!  \r\nI\'m a bit busy, quite a few @profession have been here.  Lets see.  I don\'t currently have any clean apparatus, but I can ask som Dog Soldiers to rummage around in our clinical waste to see if there is something suitable for you.</Text>\r\n<Branch Node=\"2\">I\'ll accept anything you have.</Branch>\r\n<Branch Node=\"3\">I deserve only the best.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Well before we start remaping genenomes we nead a lab!!  Lets start by having you clean this Filthy Beaker the hounds have just found.  You will nead Chromium Ore and Sulphur to scour it clean.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>My, you are a lippy one aren\'t you.\r\nGoodbye.</Text>\r\n<Flags>1</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">6147</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Clean the Filthy Beaker, using Sulphur and Chromium ore.</Description>\r\n<Completion ID=\"8\">5907</Completion>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Return to Essence Research Laboratory (Arduinne Planet) with the Pristine Beaker.</Description>\r\n<Completion ID=\"5\">4095</Completion>\r\n<Completion ID=\"13\" Count=\"1\">5907</Completion>\r\n<Completion ID=\"19\">1267</Completion>\r\n<Completion ID=\"21\">1</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Wow that\'s one clean beaker on to the next step</Text>\r\n<Branch Node=\"2\">Yes.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Next we will need a Radiated Petri Dish. so let get to it.. this should not be too to hard.  Take this dish to a terminal with the Sterilized Petri Dish and some Minosium.  This should provide you with what you need.\r\n</Text>\r\n<Branch Node=\"3\">I\'m on my way.</Branch>\r\n<Branch Node=\"4\">I can\'t be asked to do this.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Off you go, hurry up before the beaker becomes dirty!</Text>\r\n<Flags Data=\"4\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>You are stating to get on my nerves.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>Prepare a Radiated Petri Dish.</Description>\r\n<Completion ID=\"8\">3925</Completion>\r\n</Stage>\r\n<Stage ID=\"5\">\r\n<Description>Take the Radiated Petri Dish and show it to Annia Severa.</Description>\r\n<Completion ID=\"5\">4095</Completion>\r\n<Completion ID=\"13\" Count=\"1\">3925</Completion>\r\n<Completion ID=\"19\">1267</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Ah thats the perfect glow needed to erradicate almost all known life.</Text>\r\n<Branch Node=\"2\">Continue</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>There\'s one more thing needed to assist you in your project.  We need to create a nutrient broth.  Oh, all your equipment needs to be irradiated using Minosium, and this includes that pristine beaker.\r\n\r\n\r\nNutrient gel is created from Nitrogen and Grail Water.  \r\nThe best experiment to start on is to propagate vacuum stalks.  Come back to me when you have irradiated all your equipment, created the nutrient gel and produced a Vegetative Propagation Experiment.</Text>\r\n<Branch Node=\"3\">I love a challenge!</Branch>\r\n<Branch Node=\"4\">This is not for me, goodbye.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You are showing promise.</Text>\r\n<Flags Data=\"6\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>I think Ionnoa needs to look at your genemap before your next itteration.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"6\">\r\n<Description>Create a Vegetative Propogation Experiment.</Description>\r\n<Completion ID=\"8\">3509</Completion>\r\n</Stage>\r\n<Stage ID=\"7\">\r\n<Description>Show your Vegetative Propogation Experiment to Anna Severai </Description>\r\n<Completion ID=\"5\">4095</Completion>\r\n<Completion ID=\"13\" Count=\"1\">3509</Completion>\r\n<Completion ID=\"2\" Count=\"1\">3509</Completion>\r\n<Completion ID=\"19\">1267</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Well @name.\r\nThat looks like a perfect Vegetative Propogation Experiment.  \r\n\r\nLet\'s continue your training.</Text>\r\n<Branch Node=\"2\">Ok.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Next I want you to head over to  see an old collegue of mine called Caius Baro in the Valkyre Twins Sector.  You will be learning one of the core skills of a genetic scientist, how to create an enucleated egg that can take your chosen genetic experimental material.</Text>\r\n<Flags>4</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"8\">\r\n<Description>Visit Caius Baro in Valkyrie Twins to learn how to create a genetic receptical for your chosen genetic material.</Description>\r\n<Completion ID=\"5\">1705</Completion>\r\n<Completion ID=\"19\">15539</Completion>\r\n<Tree Node=\"1\">\r\n<Text>About time you got here, @name.\r\nAccorfing to Annia you\'re quite the slacker.  I don\'t think she expects you to succeed.  \r\n\r\n\r\nAnyway, let\'s get this done so you can rub your success in her face and I can get back to my work.  What exactly are you doing?</Text>\r\n<Branch Node=\"2\">I\'ve created a Vegetation experiment and now want to learn more.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ah, you\'ve come to the right person then!\r\n\r\nI\'ll train you how to remove the nucelus from the cells of the receptical for your experiment.  We tend to use Ouraboros Worms eggs, you should require about 3 to make this work. \r\n\r\nBy enucleating the cells, literally removing the nuclear material, we add the donor genetic material, which will then grow using the receptor enucleated cells.  What are you waiting for?  Bring me 3 Ouraboros Worm Eggs!</Text>\r\n<Branch Node=\"3\">I\'ll get them.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>I\'ll be waiting.</Text>\r\n<Flags Data=\"9\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"9\">\r\n<Description>Obtain 3 Ouraboros Eggs and return to Caius Baro in the Valkyre Twins Sector.</Description>\r\n<Completion ID=\"5\">1705</Completion>\r\n<Completion ID=\"13\" Count=\"3\">5559</Completion>\r\n<Completion ID=\"2\" Count=\"3\">5559</Completion>\r\n<Completion ID=\"19\">15539</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Right @name, now I want you to create a Storm Gull Cloning Kit, to show you understand the genetic engineering process.  You will need a Storm Gull Wing for the donor genetic material, and the following equipment:\r\n\r\n\r\nFirst you need to irradiate this Steralised Reagent Bottle I am going to give to you.  Then you need to add the Gull Wing to some Dry Ice in the Irradiated Reagent Bottle to make the Storm Gull Specimin.  Finally, at a manufacturing terminal you need to build a Storm Gull Cloning Kit.</Text>\r\n<Branch Node=\"2\">Erm, ok.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Did you understand what I said?\r\n\r\nTake the Storm Gull Cloning Kit back to Annia Severa to demonstrate you know what to do.</Text>\r\n<Branch Node=\"1\">Sorry, can you recap what I have to do?</Branch>\r\n<Branch Node=\"3\">I am ready</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Off you go then.</Text>\r\n<Flags Data=\"10\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">3453</Reward>\r\n</Stage>\r\n<Stage ID=\"10\">\r\n<Description>Show your Storm Gull Cloning Kit to Annia Severa on the Essence Research Laboratory (Arduinne Planet).</Description>\r\n<Completion ID=\"5\">4095</Completion>\r\n<Completion ID=\"13\" Count=\"3\">5904</Completion>\r\n<Completion ID=\"19\">1267</Completion>\r\n<Completion ID=\"21\">1</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Well @name, you have been busy.\r\n\r\n\r\n\r\n\r\nHmm..  This is quite a good effort.  I didn\'t think you had it in you.  I can now see that you are ready for the next stage.  Take these Mutated Biostructs to Drusus Bellator at the Mutation Viability Field Lab (Near Detention Centre Onorum in Asteroid Belt Gamma).  </Text>\r\n<Branch Node=\"2\">Ok</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Just don\'t let those merius militia get their hands on them.</Text>\r\n<Flags Data=\"11\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5517</Reward>\r\n</Stage>\r\n<Stage ID=\"11\">\r\n<Description>Go to Drusus Bellator at the Mutation Viability Field Lab. (Near Detention Center Onorum, Asteroid Belt Gamma). </Description>\r\n<Completion ID=\"5\">1079</Completion>\r\n<Completion ID=\"13\" Count=\"1\">5517</Completion>\r\n<Completion ID=\"2\" Count=\"1\">5517</Completion>\r\n<Completion ID=\"19\">1697</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Ok, @name, I want you to prove to me you can step up your research.\r\nI will now instruct you in how to refine a Viable Mutation Strain A1</Text>\r\n<Branch Node=\"2\">Cool.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>You will need to be able to obtain the following:\r\nRefined Zoisium, Refined Minosium, Refined Bromide and Refined Potassium.\r\nJuoona Brain and Scuttle Wing,\r\n\r\nCan you obtain these?</Text>\r\n<Branch Node=\"3\">Yes</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Right, you will need to Irradiate a Steralized Graduated Cylander and a Steralized Test Tube.  You will need to refine Fluorine, Bromide and Potassium to make the Chem Stim.  </Text>\r\n<Branch Node=\"4\">I have written this down so far.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Then simply refine the Juoona Brain, Scuttle Wing and Ziosium combined with the enzyme Chem Stim in the apparatus Radiated Test Tube and Radiated Graduated Cylinder.  This produces the Viable Mutation Strain 1A.</Text>\r\n<Branch Node=\"5\">Ok</Branch>\r\n<Branch Node=\"2\">Can you repeat what you said?</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Return to me when you have obtained the Viable Mutation Strain A1</Text>\r\n<Flags Data=\"12\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"12\">\r\n<Description>Return the Viable Mutation strain 1A to Drusus Bellator.   </Description>\r\n<Completion ID=\"13\" Count=\"1\">3567</Completion>\r\n<Completion ID=\"2\" Count=\"1\">3567</Completion>\r\n<Completion ID=\"19\">1697</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Now thats what I call a viable strain, @name.</Text>\r\n<Branch Node=\"2\">So what now?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Now I want you to prove to Annia Severa that you can create an Interpolative Gene Remapping Apparatus.  I have uploaded the schematics into your build list.  If you give one to her she will award you the call forward skill.</Text>\r\n<Branch Node=\"3\">Check.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Off you go, @profession.</Text>\r\n<Flags Data=\"13\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"11\">5906</Reward>\r\n</Stage>\r\n<Stage ID=\"13\">\r\n<Description>Take the Interpolative Gene Remapping Apparatus back to Annia Severa as proof of your skills in genetic research.   </Description>\r\n<Completion ID=\"5\">4095</Completion>\r\n<Completion ID=\"13\" Count=\"1\">5906</Completion>\r\n<Completion ID=\"2\" Count=\"1\">5906</Completion>\r\n<Completion ID=\"19\">1267</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Well you have done well haven\'t you?\r\n</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"9\">11</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Wierd Science [Version 1.0.S]', '112', '0', '0');
INSERT INTO `missions` VALUES ('379', '<Mission ID=\"379\" forfeitable=\"1\" time=\"0\">\r\n<Name>I HAVE YOUR PLUTONIUM  [Version 1.2.Prog]</Name>\r\n<Summary>I HAVE THE PLUTONIUM YOU WANTED, MAGUS.</Summary>\r\n<Condition ID=\"5\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"13\" Count=\"300\">2879</Completion>\r\n<Completion ID=\"2\" Count=\"300\">2879</Completion>\r\n<Completion ID=\"1\">456</Completion>\r\n<Tree Node=\"1\">\r\n<Text>GREAT.\r\nPLUTONIUM ORE.  IT MAKES A DECENT BANG.  CAN YOU GO AND GET ME SOMETHING ELSE?  IF I CAN MIX IT WITH REFINED URANIUM IT SHOULD MAKE A REALLY LOUD NOISE!!</Text>\r\n<Branch Node=\"2\">Ok I\'ll see what I can do.</Branch>\r\n<Branch Node=\"3\">OK I\'LL GET IT YOU</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I\'M SORRY I DID NOT HEAR YOU.  SPEAK UP.</Text>\r\n<Branch Node=\"3\">OK I\'LL GET IT YOU</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>WHAT I WANT FROM YOU IS SOME REFINED URANIUM.\r\nBRING ME BACK SOME OF THIS AND YOU WILL TRUELY MAKE ME HAPPY.  </Text>\r\n<Branch Node=\"4\">CONSIDER IT DONE.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>I\'LL BE WAITING FOR YOU!!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>TAKE A STACK OF REFINED URANIUM TO STRATIA MAGUS.</Description>\r\n<Completion ID=\"13\" Count=\"60\">3395</Completion>\r\n<Completion ID=\"2\" Count=\"60\">3395</Completion>\r\n<Completion ID=\"1\">456</Completion>\r\n<Tree Node=\"1\">\r\n<Text>SWEET!\r\nTHIS SHOULD ROCK THE PARTY!  WHAT I COULD NOW DO WITH IS SOME SLIME BALLS.  THIS AMMUNITION MAKES EXCELLENT BINDING MATERIAL FOR THE EXPERIMENTAL COMPOUND I\'M TRYING TO MAKE.</Text>\r\n<Branch Node=\"2\">SLIME BALLS ?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>SLIME BALLS, COMES OFF CREATURES IN ARAGOTH I BELIEVE.  I NEED ABOUT TEN OF THEM TO MAKE THIS PROPPERLY WORK.  CAN YOU GET THEM ME?</Text>\r\n<Branch Node=\"4\">YES</Branch>\r\n<Branch Node=\"3\">NO</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>WELL, I\'M SORRY TO HEAR THAT, I\'LL GIVE YOU SOMETHING FOR GETTING THE PLUTONIUM ORE AND THE REFINED URANIUM.  THANK YOU FOR THE TRADE.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>EXCELLENT.\r\n\r\nJUST DON\'T TARRY TOO LONG, I THINK THESE ARE STARTING TO WARM UP IF YOU GET MY GIST.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"4\">15000</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>BRING 10 SLIME BALLS TO STRATIA MAGUS.</Description>\r\n<Completion ID=\"13\" Count=\"10\">682</Completion>\r\n<Completion ID=\"2\" Count=\"10\">682</Completion>\r\n<Completion ID=\"1\">456</Completion>\r\n<Tree Node=\"1\">\r\n<Text>SLIME BALLS.  \r\nTAKE A SEAT WHILE I BREAK THEM OPEN.  YOU SEE IF YOU MIX THIS WITH POWDERED PLUTONIUM ORE, LOOK IT FIZZLES..</Text>\r\n<Branch Node=\"2\">ISN\'T THAT DANGEROUS?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>NAH, IT\'S SAFE.  THIS GLOOP I NOW WILL LAYER BETWEEN URANIUM FOIL PLATES.  AFTER A FEW HOURS YOU CAN SHAPE THE MULTI-LAYER INTO ANYTHING YOU LIKE.  ANYTHING.  IMAGINE THE POSSIBILITIES.</Text>\r\n<Branch Node=\"3\">YES.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>WHAT I WANT YOU TO GET ME NOW IS FIFTEEN ZIOSITE. IF YOU BRING THIS TO ME, THEN I\'LL LET EVERRO OVER THERE GIVE YOU A SHIELD HE\'S BEEN HOLDING FOR ME.</Text>\r\n<Branch Node=\"4\">SORRY, I\'LL HAVE TO BOW OUT OF THIS.</Branch>\r\n<Branch Node=\"5\">I\'LL GET YOU  15   ZIOSITE..</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>THATS A SHAME.\r\nUNFORTUNATELY, I\'VE GOT NO REWARD FOR YOU AT THE MOMENT.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>THAT\'S THE SPIRIT!\r\nNO, I\'LL MAKE IT  SUPRISE FOR YOU!!</Text>\r\n<Flags Data=\"3\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>TAKE 15 ZIOSITE TO STRATIA MAGUS.</Description>\r\n<Completion ID=\"13\" Count=\"15\">3021</Completion>\r\n<Completion ID=\"2\" Count=\"15\">3021</Completion>\r\n<Completion ID=\"1\">456</Completion>\r\n<Tree Node=\"1\">\r\n<Text>ZIOSITE.\r\nEXCELLENT.  THIS HEAT RESISTANT SILICATE WILL BE ABLE TO CONTAIN THE SHAPED EXPLOSIVE FOR USE IN EXPERIMENTAL PROJECTILE AMMUNTION.  \r\n\r\nI WOULD ASK YOU TO TEST IT FOR ME, BUT THAT\'S FORBIDDEN.\r\nINSTEAD, WHY DON\'T YOU COLLECT THE ITEM EVERRO HAS BEEN HOLDING FOR YOU?</Text>\r\n<Flags Data=\"4\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>COLLECT YOUR REWARD FROM EVERRO</Description>\r\n<Completion ID=\"1\">457</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Why do you do it @name?  \r\nWhy bring him that gear!  Do you want him to have another itteration??\r\nI\'ll give you this reward if you never get him any more gear!  Its\' never safe with that pyromaniac around this station.</Text>\r\n<Branch Node=\"2\">I\'ll agree if you give me the reward,</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Here, have this waterloo shield.  Its\' taking up space.</Text>\r\n<Branch Node=\"3\">Oooooooo....</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Have fun.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">3720</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'I HAVE YOUR PLUTONIUM  [Version 1.2.Prog]', '456', '0', '0');
INSERT INTO `missions` VALUES ('380', '<Mission ID=\"380\" forfeitable=\"1\" time=\"0\">\r\n<Name>I HAVE YOUR PLUTONIUM  [Version 1.2.TJ]</Name>\r\n<Summary>I HAVE THE PLUTONIUM YOU WANTED, MAGUS.</Summary>\r\n<Condition ID=\"5\">1</Condition>\r\n<Condition ID=\"5\">0</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"13\" Count=\"300\">2879</Completion>\r\n<Completion ID=\"13\" Count=\"300\">2879</Completion>\r\n<Completion ID=\"2\" Count=\"300\">2879</Completion>\r\n<Completion ID=\"2\" Count=\"300\">2879</Completion>\r\n<Completion ID=\"1\">456</Completion>\r\n<Tree Node=\"1\">\r\n<Text>GREAT.\r\nPLUTONIUM ORE.  IT MAKES A DECENT BANG.  CAN YOU GO AND GET ME SOMETHING ELSE?  IF I CAN MIX IT WITH REFINED URANIUM IT SHOULD MAKE A REALLY LOUD NOISE!!</Text>\r\n<Branch Node=\"2\">Ok I\'ll see what I can do.</Branch>\r\n<Branch Node=\"3\">OK I\'LL GET IT YOU</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I\'M SORRY I DID NOT HEAR YOU.  SPEAK UP.</Text>\r\n<Branch Node=\"3\">OK I\'LL GET IT YOU</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>WHAT I WANT FROM YOU IS SOME REFINED URANIUM.\r\nBRING ME BACK SOME OF THIS AND YOU WILL TRUELY MAKE ME HAPPY.  </Text>\r\n<Branch Node=\"4\">CONSIDER IT DONE.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>I\'LL BE WAITING FOR YOU!!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>TAKE TWO STACKS OF REFINED URANIUM TO STRATIA MAGUS.</Description>\r\n<Completion ID=\"13\" Count=\"120\">3395</Completion>\r\n<Completion ID=\"2\" Count=\"120\">3395</Completion>\r\n<Completion ID=\"1\">456</Completion>\r\n<Tree Node=\"1\">\r\n<Text>SWEET!\r\nTHIS SHOULD ROCK THE PARTY!  WHAT I COULD NOW DO WITH IS SOME SLIME BALLS.  THIS AMMUNITION MAKES EXCELLENT BINDING MATERIAL FOR THE EXPERIMENTAL COMPOUND I\'M TRYING TO MAKE.</Text>\r\n<Branch Node=\"2\">SLIME BALLS ?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>SLIME BALLS, COMES OFF CREATURES IN ARAGOTH I BELIEVE.  I NEED ABOUT TWENTY OF THEM TO MAKE THIS PROPPERLY WORK.  CAN YOU GET THEM ME?</Text>\r\n<Branch Node=\"4\">YES</Branch>\r\n<Branch Node=\"3\">NO</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>WELL, I\'M SORRY TO HEAR THAT, I\'LL GIVE YOU SOMETHING FOR GETTING THE PLUTONIUM ORE AND THE REFINED URANIUM.  THANK YOU FOR THE TRADE.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>EXCELLENT.\r\n\r\nJUST DON\'T TARRY TOO LONG, I THINK THESE ARE STARTING TO WARM UP IF YOU GET MY GIST.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"4\">15000</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>BRING 20 SLIME BALLS TO STRATIA MAGUS.</Description>\r\n<Completion ID=\"13\" Count=\"20\">682</Completion>\r\n<Completion ID=\"2\" Count=\"20\">682</Completion>\r\n<Completion ID=\"1\">456</Completion>\r\n<Tree Node=\"1\">\r\n<Text>SLIME BALLS.  \r\nTAKE A SEAT WHILE I BREAK THEM OPEN.  YOU SEE IF YOU MIX THIS WITH POWDERED PLUTONIUM ORE, LOOK IT FIZZLES..</Text>\r\n<Branch Node=\"2\">ISN\'T THAT DANGEROUS?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>NAH, IT\'S SAFE.  THIS GLOOP I NOW WILL LAYER BETWEEN URANIUM FOIL PLATES.  AFTER A FEW HOURS YOU CAN SHAPE THE MULTI-LAYER INTO ANYTHING YOU LIKE.  ANYTHING.  IMAGINE THE POSSIBILITIES.</Text>\r\n<Branch Node=\"3\">YES.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>WHAT I WANT YOU TO GET ME NOW IS THIRTY ZIOSITE.  IF YOU BRING THIS TO ME, THEN I\'LL LET EVERRO OVER THERE GIVE YOU A SHIELD HE\'S BEEN HOLDING FOR ME.</Text>\r\n<Branch Node=\"4\">SORRY, I\'LL HAVE TO BOW OUT OF THIS.</Branch>\r\n<Branch Node=\"5\">I\'LL GET YOU  30   ZIOSITE.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>THATS A SHAME.\r\nUNFORTUNATELY, I\'VE GOT NO REWARD FOR YOU AT THE MOMENT.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>THAT\'S THE SPIRIT!\r\nNO, I\'LL MAKE IT  SUPRISE FOR YOU!!</Text>\r\n<Flags Data=\"3\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>TAKE 30 ZIOSITE TO STRATIA MAGUS.</Description>\r\n<Completion ID=\"13\" Count=\"30\">3021</Completion>\r\n<Completion ID=\"2\" Count=\"30\">3021</Completion>\r\n<Completion ID=\"1\">456</Completion>\r\n<Tree Node=\"1\">\r\n<Text>ZIOSITE.\r\nEXCELLENT.  THIS HEAT RESISTANT SILICATE WILL BE ABLE TO CONTAIN THE SHAPED EXPLOSIVE FOR USE IN EXPERIMENTAL PROJECTILE AMMUNTION.  \r\n\r\nI WOULD ASK YOU TO TEST IT FOR ME, BUT THAT\'S FORBIDDEN.\r\nINSTEAD, WHY DON\'T YOU COLLECT THE ITEM EVERRO HAS BEEN HOLDING FOR YOU?</Text>\r\n<Flags Data=\"4\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>COLLECT YOUR REWARD FROM EVERRO</Description>\r\n<Completion ID=\"1\">457</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Why do you do it @name?  \r\nWhy bring him that gear!  Do you want him to have another itteration??\r\nI\'ll give you this reward if you never get him any more gear!  Its\' never safe with that pyromaniac around this station.</Text>\r\n<Branch Node=\"2\">I\'ll agree if you give me the reward,</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Here, have this Attacking Wing engine.  Its\' taking up space.</Text>\r\n<Branch Node=\"3\">Oooooooo....</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Have fun.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2598</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'I HAVE YOUR PLUTONIUM  [Version 1.2.TJ]', '457', '0', '0');
INSERT INTO `missions` VALUES ('381', '<Mission ID=\"381\" forfeitable=\"1\" time=\"0\">\r\n<Name>We recovered this from the Merus Militia Captain [Version 1.1.-]</Name>\r\n<Summary>Some items were recovered from the Merus Militia Captain.  For 20,000 credits you can have the first one.  50,000 credits will give you the second one and 100,000 credits the third.  Are you interested?</Summary>\r\n<Condition ID=\"5\">2</Condition>\r\n<Condition ID=\"10\">269</Condition>\r\n<Stage ID=\"0\">\r\n<Description>Some items were recovered from the Merus Militia Captain.  For 20,000 credits you can have the first one.  50,000 credits will give you the second one and 100,000 credits the third.  Are you interested?</Description>\r\n<Completion ID=\"1\">112</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Some items were recovered from the Merus Militia Captain.  For 20,000 credits you can have the first one.  50,000 credits will give you the second one and 100,000 credits the third.  Are you interested?</Text>\r\n<Branch Node=\"2\">I\'m interested.</Branch>\r\n<Branch Node=\"3\">Not for me</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok talk to me again when you have the credits.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Sorry to hear that, you won\'t be able to get these again.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Give me 20,000 credits for the loot.</Description>\r\n<Completion ID=\"1\">112</Completion>\r\n<Completion ID=\"14\">20000</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Some items were recovered from the Merus Militia Captain.  For 20,000 credits you can have the first one.  50,000 credits will give you the second one and 100,000 credits the third.  Are you interested?\r\n\r\nThe first item is an ammunition sample, here you go.\r\nDo you want to purchase the next item?</Text>\r\n<Branch Node=\"2\">No.</Branch>\r\n<Branch Node=\"3\">Yes</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Oh well, then you aren\'t interested in any more items then.\r\nGoodbye.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Great.\r\nPass the funds over.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">588</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Give me another 30,000 credits for the next one.</Description>\r\n<Completion ID=\"1\">112</Completion>\r\n<Completion ID=\"14\">30000</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Some items were recovered from the Merus Militia Captain.  For 20,000 credits you can have the first one.  50,000 credits will give you the second one and 100,000 credits the third.  Are you interested?\r\n\r\nThe second item is missile launcher, here you go.\r\nDo you want to purchase the next item?</Text>\r\n<Branch Node=\"2\">No.</Branch>\r\n<Branch Node=\"3\">Yes</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Oh well, then you aren\'t interested in any more items then.\r\nGoodbye.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Great.\r\nPass the funds over.</Text>\r\n<Flags Data=\"3\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2720</Reward>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Give me 50,000 credits for the final one.</Description>\r\n<Completion ID=\"1\">112</Completion>\r\n<Completion ID=\"14\">50000</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Some items were recovered from the Merus Militia Captain.  For 20,000 credits you can have the first one.  50,000 credits will give you the second one and 100,000 credits the third.  Are you interested?\r\n\r\nThe last item is a reactor, here you go.</Text>\r\n<Branch Node=\"2\">Thank you.</Branch>\r\n<Branch Node=\"3\">No thanks.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Enjoy these items.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>I\'m sorry to hear that</Text>\r\n<Flags>3</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">3250</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'We recovered this from the Merus Militia Captain [Version 1.1.-]', '112', '0', '0');
INSERT INTO `missions` VALUES ('382', '<Mission ID=\"382\" forfeitable=\"1\" time=\"0\">\r\n<Name>Probe the Lines [Version 2.1.-]</Name>\r\n<Summary>Signifier Corniculairus requires you to check the Terran Alliance lines for weakness.</Summary>\r\n<Condition ID=\"10\">399</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">635</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Right @name.\r\n\r\nI will say this only once. \r\nYour mission is to probe the Terran Lines.   This is the first mission to assess your suitability at this task.  Do not dissapoint me. </Text>\r\n<Branch Node=\"2\">Yes Sir!</Branch>\r\n<Branch Node=\"4\">I don\'t want to kill Terrans.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Terminate with extreme predudice the following ships: \r\n\r\n3 x Terran Alliance Ensigns\r\n2 x Terran Alliance Lieutenants\r\n</Text>\r\n<Branch Node=\"3\">I\'m on my way.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Stay alive,</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>You don\'t deserve that award.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Kill Mob!</Description>\r\n<Completion ID=\"4\" Count=\"3\">2071</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Kill Mob!</Description>\r\n<Completion ID=\"4\" Count=\"2\">2072</Completion>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Return to Signifier Corniculairus on PAX Remar</Description>\r\n<Completion ID=\"1\">633</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nReport.</Text>\r\n<Branch Node=\"2\">Their lines look a little weak Sir.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Well done @name.\r\nCome back to me again, I may have a mission for you.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"27\">100</Reward>\r\n<Reward ID=\"3\">6000</Reward>\r\n<Reward ID=\"2\">6000</Reward>\r\n<Reward ID=\"4\">6000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Probe the Lines [Version 2.1.-]', '633', '0', '0');
INSERT INTO `missions` VALUES ('383', '<Mission ID=\"383\" forfeitable=\"1\" time=\"0\">\r\n<Name>Ammunition Supply to the Progen Combine Fleet [Version 2.1.0]</Name>\r\n<Summary>The Signifier Cornicularius based with the Progen Combine Fleet in 61 Cygni requires ammunition. \r\nTake it to him.</Summary>\r\n<Condition ID=\"10\">399</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"6\">0</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">642</Completion>\r\n<Tree Node=\"1\">\r\n<Text>The *hic* PAX Remar in 61 Cygni is *hic* expecting you to bring them:\r\n5000 rounds of Plasma *hic* Mortar Ammunition\r\n5000 rounds of Projectile Mortar Ammunition.\r\n\r\nCan *hic* you supply them?  </Text>\r\n<Branch Node=\"2\">Yes Ma\'am!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\nGo and see the Signifier in *hic* the Briefing Room of the PAX Remar.\r\n\r\nIf you *hic* see any of the Terran Taskforce.  Kill them.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver 5,000 rounds of Mortar Plasma Ammunition to the Signifier on the PAX Remar in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"5000\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"2\" Count=\"500\">657</Completion>\r\n<Completion ID=\"1\">635</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nHurry up my fighters need these.\r\nSupply the Mortar Projectile Ammunition and we\'ll settle up.</Text>\r\n<Branch Node=\"2\">OK, here you go.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Quick.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Deliver 5,000 rounds of Mortar Projectile Ammunition to the Signifier on the PAX Remar in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"5000\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"2\" Count=\"500\">658</Completion>\r\n<Completion ID=\"1\">635</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, we were running low of these supplies.  Have this reward.\r\nDo me a favour, kill any Terran you see in this sector.</Text>\r\n<Branch Node=\"2\">Thanks</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Enjoy.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"27\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Ammunition Supply to the Progen Combine Fleet [Version 2.1.0]', '642', '0', '0');
INSERT INTO `missions` VALUES ('384', '<Mission ID=\"384\" forfeitable=\"1\" time=\"0\">\r\n<Name>Resource Supply to the Progen Combine Fleet [Version 2.1.0]</Name>\r\n<Summary>The Signifier Cornicularius based with the Progen Combine Fleet in 61 Cygni requires resources. \r\nTake these to him.</Summary>\r\n<Condition ID=\"10\">399</Condition>\r\n<Condition ID=\"6\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">642</Completion>\r\n<Tree Node=\"1\">\r\n<Text>The PAX Remar in 61 Cygni is expecting you to bring them:\r\n10 x Stacks of Refined Homerium\r\n10 x Stacks of Refined Osirium\r\n\r\nCan you supply them?  *hic*</Text>\r\n<Branch Node=\"2\">Yes Ma\'am!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.  *hic*\r\nGo and see the Signifier in the Briefing Room of the PAX Remar.\r\n\r\nIf you see any of the Terran Taskforce.  Kill them.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver  10 x Stacks of Refined Homerium to the Signifier on the PAX Remar in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"600\">3520</Completion>\r\n<Completion ID=\"2\" Count=\"500\">3520</Completion>\r\n<Completion ID=\"2\" Count=\"100\">3520</Completion>\r\n<Completion ID=\"1\">635</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nHurry up my engineers needs these.\r\nSupply the Refined Osirium and we\'ll settle up.</Text>\r\n<Branch Node=\"2\">OK, here you go.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Quick.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Deliver  10 x Stacks of Refined Osirium to the Signifier on the PAX Remar in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"600\">3520</Completion>\r\n<Completion ID=\"2\" Count=\"500\">3520</Completion>\r\n<Completion ID=\"2\" Count=\"100\">3520</Completion>\r\n<Completion ID=\"1\">635</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, we were running low of these supplies.  Have this reward.\r\nDo me a favour, kill any Terran you see in this sector.</Text>\r\n<Branch Node=\"2\">Thanks</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Enjoy.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"27\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Resource Supply to the Progen Combine Fleet [Version 2.1.0]', '642', '0', '0');
INSERT INTO `missions` VALUES ('385', '<Mission ID=\"385\" forfeitable=\"1\" time=\"0\">\r\n<Name>Device Supply to the Progen Combine Fleet [Version 2.1.0]</Name>\r\n<Summary>The Signifier Cornicularius based with the Progen Combine Fleet in 61 Cygni requires devices. \r\nTake these to him.</Summary>\r\n<Condition ID=\"10\">399</Condition>\r\n<Condition ID=\"6\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">642</Completion>\r\n<Tree Node=\"1\">\r\n<Text>The PAX Remar in *hic* 61 Cygni is expecting you to bring them:\r\n10 *hic* Energy Sink Senio\'s\r\n\r\nCan you supply them?  *hic* *hic*</Text>\r\n<Branch Node=\"2\">Yes Ma\'am!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\nGo and see the *hic* Signifier in the Briefing Room of the PAX Remar.\r\n\r\nIf you see any *hic* of the Terran Taskforce.  Kill them.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver  10 x Energy Sink Senio\'s to the Signifier on the PAX Remar in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"10\">2186</Completion>\r\n<Completion ID=\"2\" Count=\"10\">2186</Completion>\r\n<Completion ID=\"1\">635</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, we were running low of these supplies.  Have this reward.\r\nDo me a favour, kill any Terran you see in this sector.</Text>\r\n<Branch Node=\"2\">Thanks</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Enjoy.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"27\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Device Supply to the Progen Combine Fleet [Version 2.1.0]', '642', '0', '0');
INSERT INTO `missions` VALUES ('386', '<Mission ID=\"386\" forfeitable=\"1\" time=\"0\">\r\n<Name>Shield Supply to the Progen Combine Fleet [Version 2.1.0]</Name>\r\n<Summary>The Signifier Cornicularius based with the Progen Combine Fleet in 61 Cygni requires Shields. \r\nTake these to him.</Summary>\r\n<Condition ID=\"10\">399</Condition>\r\n<Condition ID=\"4\">30</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">642</Completion>\r\n<Tree Node=\"1\">\r\n<Text>The PAX Remar in 61 Cygni is expecting *hic* you to bring them:\r\n10 x Waterloo VI\'s\r\n\r\nCan you supply them?  *hic*</Text>\r\n<Branch Node=\"2\">Yes Ma\'am!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\n*hic* Go and see the Signifier in the Briefing Room of the PAX Remar.\r\n\r\nIf you see any of the Terran Taskforce.  Kill them. *hic*</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver  10 x Waterloo VI\'s to the Signifier on the PAX Remar in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"10\">3720</Completion>\r\n<Completion ID=\"2\" Count=\"10\">3720</Completion>\r\n<Completion ID=\"1\">635</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, we were running low of these supplies.  Have this reward.\r\nDo me a favour, kill any Terran you see in this sector.</Text>\r\n<Branch Node=\"2\">Thanks</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Enjoy.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"27\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Shield Supply to the Progen Combine Fleet [Version 2.1.0]', '642', '0', '0');
INSERT INTO `missions` VALUES ('387', '<Mission ID=\"387\" forfeitable=\"1\" time=\"0\">\r\n<Name>Weapon Supply to the Progen Combine Fleet [Version 2.1.0]</Name>\r\n<Summary>The Signifier Cornicularius based with the Progen Combine Fleet in 61 Cygni requires weapons. \r\nTake these to him.</Summary>\r\n<Condition ID=\"10\">399</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"6\">0</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">642</Completion>\r\n<Tree Node=\"1\">\r\n<Text>The PAX Remar in 61 Cygni is expecting you to bring *hic* them:\r\n*hic* 10 x Mortar Alpha\'s *hic*\r\n\r\nCan *hic* you supply them?  </Text>\r\n<Branch Node=\"2\">Yes Ma\'am!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\nGo and see the Signifier in the Briefing *hic* Room of the PAX Remar.\r\n\r\nIf *hic* you see any of the Terran *hic* Taskforce.  Kill them.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver  10 x Mortar Alpha\'s to the Signifier on the PAX Remar in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"10\">3114</Completion>\r\n<Completion ID=\"2\" Count=\"10\">3114</Completion>\r\n<Completion ID=\"1\">635</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, we were running low of these supplies.  Have this reward.\r\nDo me a favour, kill any Terran you see in this sector.</Text>\r\n<Branch Node=\"2\">Thanks</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Enjoy.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"27\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Weapon Supply to the Progen Combine Fleet [Version 2.1.0]', '642', '0', '0'), ('388', '<Mission ID=\"388\" forfeitable=\"1\" time=\"0\">\r\n<Name>Classified: Supply Mission [Version 1.0.0]</Name>\r\n<Summary>You are needed to provide CENSORED to CENSORED on the CENSORED in CENSORED.  </Summary>\r\n<Condition ID=\"2\">50</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Condition ID=\"9\" Flags=\"4007\">1</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Condition ID=\"10\">253</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"13\" Count=\"1\">4007</Completion>\r\n<Completion ID=\"1\">636</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome @name, grab yourself a drink and I\'ll tell you what I want.\r\n\r\nMemorise what I say, because it will not be written down anywhere for you!\r\n</Text>\r\n<Branch Node=\"2\">I\'m listening.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I hear that the Crimson Force Barrier shield can be obtained?  \r\nPacurius Stratelates on the PAX Remar require X samples in order to configure a REMORA ASSAULT CRAFT with an Advanced Penatration Ram.\r\n\r\nCan you obtain them for us?</Text>\r\n<Branch Node=\"3\">Yes</Branch>\r\n<Branch Node=\"4\">No</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Great.\r\nPacurius Stratelates will be waiting for you.  Make sure you have your Symbol of Honor equipped as he only converses with heros.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>I\'d be careful how many of these missions you turn down, @profession.  You may burn your bridges with us.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>CLASSIFIED - You had a briefing, it is up to you to remember.</Description>\r\n<Completion ID=\"13\" Count=\"1\">4007</Completion>\r\n<Completion ID=\"2\" Count=\"6\">3795</Completion>\r\n<Completion ID=\"1\">634</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@name.\r\nYou made it then?  Thats\' good.  Hand over the supplies.</Text>\r\n<Branch Node=\"2\">Yes Sir.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>These look fine.  \r\n\r\nI may need your services in future, be sure to check with me or Anthemiolus Troglita.  I provide the Classified Covert missions and Troglita gives out the Classified Combat missions.  Signifiers deal with new recruits.\r\n\r\nJust remember, that Symbol of Honor is rare, keep it safe as it is very hard to obtain another!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"27\">150</Reward>\r\n<Reward ID=\"4\">20000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Classified: Supply Mission [Version 1.0.0]', '636', '0', '0');
INSERT INTO `missions` VALUES ('389', '<Mission ID=\"389\" forfeitable=\"1\" time=\"0\">\r\n<Name>Ammunition Supply to the Terran Alliance Fleet [Kyp 2.1.0]</Name>\r\n<Summary>Quartermaster Kaden based with the Terran Alliance Fleet in 61 Cygni requires ammunition. \r\nTake it to him.</Summary>\r\n<Condition ID=\"10\">400</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"6\">0</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">226</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome, @profession, we have engaged the Progen Fleet in 61 Cygni and are in needs of the following supplies:\r\n\r\n2500 Plasma Rocket Type Z3\r\n2500 EMP Rocket Type Z3\r\n\r\nCan you supply them?  </Text>\r\n<Branch Node=\"2\">Yes miss!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\nGo and see the Quatermaster in the Supply Center of the ECS Bremen.\r\n\r\nSee any Progen Scum, Slay them all!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver 2,500 Plasma Rocket Type Z3 Missiles to the Quatermaster Kaden on the ECS Bremen in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"2500\">697</Completion>\r\n<Completion ID=\"2\" Count=\"500\">697</Completion>\r\n<Completion ID=\"2\" Count=\"500\">697</Completion>\r\n<Completion ID=\"2\" Count=\"500\">697</Completion>\r\n<Completion ID=\"2\" Count=\"500\">697</Completion>\r\n<Completion ID=\"2\" Count=\"500\">697</Completion>\r\n<Completion ID=\"1\">638</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nHurry up my fighters need these.\r\nYou have got my order, dontcha?</Text>\r\n<Branch Node=\"2\">Yes, here you go, sir.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Quickly, now!</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Deliver 2,500 EMP Rocket Type Z3 Missiles to the Quatermaster Kaden on the ECS Bremen in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"5000\">693</Completion>\r\n<Completion ID=\"2\" Count=\"500\">693</Completion>\r\n<Completion ID=\"2\" Count=\"500\">693</Completion>\r\n<Completion ID=\"2\" Count=\"500\">693</Completion>\r\n<Completion ID=\"2\" Count=\"500\">693</Completion>\r\n<Completion ID=\"2\" Count=\"500\">693</Completion>\r\n<Completion ID=\"1\">638</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, we were running low on ammo, these progen sure don\'t mind dyin\'.  Have this reward. Remember the only good progen is a dead one.</Text>\r\n<Branch Node=\"2\">Thanks, I\'ll keep that in mind.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Don\'t spend it all in one place!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"28\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Ammunition Supply to the Terran Alliance Fleet [Kyp 2.1.0]', '226', '0', '0');
INSERT INTO `missions` VALUES ('390', '<Mission ID=\"390\" forfeitable=\"1\" time=\"0\">\r\n<Name>Engine Supply to the Terran Alliance Fleet [Kyp 2.1.0]</Name>\r\n<Summary>Quartermaster Kaden based with the Terran Alliance Fleet in 61 Cygni requires engines. \r\nTake them to him.</Summary>\r\n<Condition ID=\"10\">400</Condition>\r\n<Condition ID=\"4\">30</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">226</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome, @profession, we have engaged the Progen Fleet in 61 Cygni and are in needs of the following supplies:\r\n\r\n10 x Attacking Wings\r\n\r\nCan you supply them?  </Text>\r\n<Branch Node=\"2\">Yes miss!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\nGo and see the Quartermaster in the Supply Center of the ECS Bremen.\r\n\r\nSee any Progen Scum, Slay them all!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver 10 x Attacking Wings to Quatermaster Kaden on the ECS Bremen in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"10\">2598</Completion>\r\n<Completion ID=\"2\" Count=\"10\">2598</Completion>\r\n<Completion ID=\"1\">638</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, we are hoping to modify some of our mobile weapons in this sector.\r\nRemember, the only good Progen, is a dead one.</Text>\r\n<Branch Node=\"2\">Thanks, I\'ll keep that in mind.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Don\'t spend it all in one place!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"28\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Engine Supply to the Terran Alliance Fleet [Kyp 2.1.0]', '638', '0', '0'), ('391', '<Mission ID=\"391\" forfeitable=\"1\" time=\"0\">\r\n<Name>Resource Supply to the Terran Alliance Fleet [Kyp 2.1.0]</Name>\r\n<Summary>Quartermaster Kaden based with the Terran Alliance Fleet in 61 Cygni requires refined resources. \r\nTake it to him.</Summary>\r\n<Condition ID=\"10\">400</Condition>\r\n<Condition ID=\"6\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">226</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome, @profession, we have engaged the Progen Fleet in 61 Cygni and are in needs of the following supplies:\r\n\r\n10 stacks of Rainbow Silicon\r\n10 stacks of Platinum\r\n\r\nCan you supply them?  </Text>\r\n<Branch Node=\"2\">Yes miss!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\nGo and see the Quartermaster in the Supply Center of the ECS Bremen.\r\n\r\nSee any Progen Scum, Slay them all!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver 10 stacks of Rainbow Silicon to Quatermaster Kaden on the ECS Bremen in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"600\">3531</Completion>\r\n<Completion ID=\"2\" Count=\"500\">3531</Completion>\r\n<Completion ID=\"2\" Count=\"100\">3531</Completion>\r\n<Completion ID=\"1\">638</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Quick hand them over, we don\'t have time to talk.</Text>\r\n<Branch Node=\"2\">What about my reward?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>You\'ll get the reward after you supply the Refined Platinum.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Deliver 10 stacks of Platinum to Quatermaster Kaden on the ECS Bremen in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"600\">3528</Completion>\r\n<Completion ID=\"2\" Count=\"500\">3528</Completion>\r\n<Completion ID=\"2\" Count=\"100\">3528</Completion>\r\n<Completion ID=\"1\">638</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, this will be able to help us patch our fighters up faster.\r\nRemember, the only good Progen is a dead one!</Text>\r\n<Branch Node=\"2\">Thanks, I\'ll keep that in mind.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Don\'t spend it all in one place. See you next time!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"28\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Resource Supply to the Terran Alliance Fleet [Kyp 2.1.0]', '638', '0', '0');
INSERT INTO `missions` VALUES ('392', '<Mission ID=\"392\" forfeitable=\"1\" time=\"0\">\r\n<Name>Device Supply to the Terran Alliance Fleet [Kyp 2.1.0]</Name>\r\n<Summary>Quartermaster Kaden based with the Terran Alliance Fleet in 61 Cygni requires some Cat\'s Paw devices. Take them to him.</Summary>\r\n<Condition ID=\"10\">400</Condition>\r\n<Condition ID=\"6\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">226</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome, @profession, we have engaged the Progen Fleet in 61 Cygni and are in needs of the following supplies:\r\n\r\n10 x Cat\'s Paw L6\r\n\r\nCan you supply them?  </Text>\r\n<Branch Node=\"2\">Yes miss!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\nGo and see the Quatermaster in the Supply Center of the ECS Bremen.\r\n\r\nSee any Progen Scum, Slay them all!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver 10 x Cat\'s Paw L6\'s to Quartermaster Kaden on the ECS Bremen in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"10\">2145</Completion>\r\n<Completion ID=\"2\" Count=\"10\">2145</Completion>\r\n<Completion ID=\"1\">638</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, we are hoping to modify some of our mobile weapons in this sector.\r\nRemember, the only good progen is a dead one!</Text>\r\n<Branch Node=\"2\">Thanks, I\'ll remember that.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Don\'t spend it all in one place! See you next time!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"28\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Device Supply to the Terran Alliance Fleet [Kyp 2.1.0]', '638', '0', '0');
INSERT INTO `missions` VALUES ('393', '<Mission ID=\"393\" forfeitable=\"1\" time=\"0\">\r\n<Name>Missile Launcher Supply to the Terran Alliance Fleet [Kyp 2.1.0]</Name>\r\n<Summary>Quartermaster Kaden based with the Terran Alliance Fleet in 61 Cygni requires Missile Launchers. Take these to him.</Summary>\r\n<Condition ID=\"10\">400</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"6\">0</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">226</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome, @profession, we have engaged the Progen Fleet in 61 Cygni and are in needs of the following supplies:\r\n\r\n7 x Terrific ML Class Z3\r\n\r\nCan you supply them?  </Text>\r\n<Branch Node=\"2\">Yes miss!</Branch>\r\n<Branch Node=\"3\">No.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ok.\r\nGo and see the Quartermaster in the Supply Center of the ECS Bremen.\r\n\r\nSee any Progen Scum, Slay them all!</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>You dissapoint me, @name.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver 7 x Terrific ML Class Z3  to Quartermaster Kaden on the ECS Bremen in 61 Cygni.</Description>\r\n<Completion ID=\"13\" Count=\"7\">2783</Completion>\r\n<Completion ID=\"2\" Count=\"7\">2783</Completion>\r\n<Completion ID=\"1\">638</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@profession.\r\n\r\nWell done, these will help our ship\'s defenses.\r\nRemember, the only good progen is a dead one.</Text>\r\n<Branch Node=\"2\">Thanks, I\'ll keep that in mind.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Don\'t spend it all in one place!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"28\">5</Reward>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"4\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Missile Launcher Supply to the Terran Alliance Fleet [Kyp 2.1.0]', '638', '0', '0');
INSERT INTO `missions` VALUES ('394', '<Mission ID=\"394\" forfeitable=\"1\" time=\"0\">\r\n<Name>Scout their Lines [Kyp 2.0.0]</Name>\r\n<Summary>Go and slay some Progen Scum for credits and fame.</Summary>\r\n<Condition ID=\"10\">400</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">641</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Isn\'t it exciting, we get to go war!\r\nI\'ve never been to war before but this should be fun..  I\'m fresh from the academy.  This\'ll be fun eh?</Text>\r\n<Branch Node=\"2\">I\'m sure you\'ll go far, kid.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Anyway, we\'ve been given a vital mission.\r\nWe have to go into the Progen Combine Territory and kill some of their ships.\r\n\r\nWe want to teach their Dog Soldiers a lesson.  They have some Progen Combine REMORA Assault Craft.  These craft are used to board vessels and land on planets, and contain their Shock Troops.  \r\n</Text>\r\n<Branch Node=\"3\">So what\'s the mission, Sah?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>We don\'t have long so I\'ll tell you the mission once we launch.  It\'s my first mission!  Isn\'t this great!</Text>\r\n<Flags>4</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Destroy two Progen Combine Triemes</Description>\r\n<Completion ID=\"4\" Count=\"2\">2063</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Destroy two Progen Combine Quadiremes</Description>\r\n<Completion ID=\"4\" Count=\"2\">2064</Completion>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Intercept and destroy a Progen Combine REMORA Assault Craft</Description>\r\n<Completion ID=\"4\" Count=\"1\">2062</Completion>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>Return to the ECS Bremen and talk to your exuberant flight leader!</Description>\r\n<Completion ID=\"1\">641</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Yeah! Great job! That was kinda fun huh?\r\n\r\n13 for me and 5 notches for you, we\'ll move up the Terran Alliance ranks yet.</Text>\r\n<Branch Node=\"2\">You did Sir?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>No it was five, five dead.</Text>\r\n<Branch Node=\"3\">So my reward is?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Actually, I think you\'ll find I got three of them! Here is your reward.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"3\">6000</Reward>\r\n<Reward ID=\"4\">6000</Reward>\r\n<Reward ID=\"2\">6000</Reward>\r\n<Reward ID=\"5\" Flags=\"28\">25</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Scout their Lines [Kyp 2.0.0]', '641', '0', '0');
INSERT INTO `missions` VALUES ('395', '<Mission ID=\"395\" forfeitable=\"1\" time=\"0\">\r\n<Name>Gather Zenshai Fragments</Name>\r\n<Summary>Ketsugo Observation Outpost needs help getting rid of the Zenshai. Bring them Zenshai Fragments to prove you helped eliminate some of the Zenshai.</Summary>\r\n<Condition ID=\"10\">142</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"18\">1527</Completion>\r\n<Tree Node=\"1\">\r\n<Text>You are back again @name. I know we\'ve asked a lot from you in the pas, but we\'re still having Zenshai problems in this sector as well as in Vishao\'s Cove. </Text>\r\n<Branch Node=\"2\">Yes?</Branch>\r\n<Branch Node=\"3\">Sorry, I\'m not interested.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>If you could bring us three Zenshai Fragments to show you have killed some, we will reward you.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Ok, but we still need help. Please promise to help again soon?</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Bring 3 Zenshai Fragments back to the Ketsugo Observation Outpost in Yokan, Capella System.</Description>\r\n<Completion ID=\"2\" Count=\"3\">5736</Completion>\r\n<Completion ID=\"19\">1527</Completion>\r\n<Tree Node=\"1\">\r\n<Text>You return with the fragments, well done.</Text>\r\n<Branch Node=\"2\">Anytime.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Here\'s some credits for your work. The job well done is always welcome.</Text>\r\n<Flags Data=\"-2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"3\">2000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Gather Zenshai Fragments', '112', '0', '0');
INSERT INTO `missions` VALUES ('397', '<Mission ID=\"397\" forfeitable=\"1\" time=\"0\">\r\n<Name>Scan something</Name>\r\n<Summary>Help ayako</Summary>\r\n<Condition ID=\"10\">33</Condition>\r\n<Condition ID=\"9\" Flags=\"5746\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">123</Completion>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>.</Description>\r\n<Completion ID=\"1\">123</Completion>\r\n</Stage>\r\n</Mission>\r\n', 'Scan something', '123', '0', '0');
INSERT INTO `missions` VALUES ('398', '<Mission ID=\"398\" forfeitable=\"1\" time=\"0\">\r\n<Name>A Choice To Be Made [All Races v2.0]</Name>\r\n<Summary>BREAKING NEWS!!!  It\'s WAR in 61 Cygni - and you may want to choose a side.  Warning, if you refuse you will not be conscripted!!</Summary>\r\n<Condition ID=\"1\">30</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"5\">1071</Completion>\r\n<Completion ID=\"18\">38</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Attention, @race.\r\n\r\nBreaking News!  There is a WAR happening in 61 Cygni and both the Progen Combine and the Terran Alliance are seeking recruits.  As an impartial observer, Net 7 has been given some Draft Cards to give to prospective recruits.</Text>\r\n<Branch Node=\"2\">Draft cards?</Branch>\r\n<Branch Node=\"7\">Quick, I don\'t need to know!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Yes, @name.\r\n\r\nThe card I can give you will allow you to select one side to be on.  Remember, although you may speak to both sides, you may only select one.  From what I hear they have made this a \'local matter\', with opposing factions.</Text>\r\n<Branch Node=\"3\">What Factions?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>The Terran Alliance and Progen Combine \r\n\r\nThese are the two factions that directly oppose each other in this sector.  Any time you gain one you will loose double the other.  Make your choice wisely.</Text>\r\n<Branch Node=\"4\">The Progens?</Branch>\r\n<Branch Node=\"5\">The Terrans?</Branch>\r\n<Branch Node=\"6\">The Jenquia?</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>The representive for the Progen Combine can be found in the bar area of Arx Magister (Mars).  She has quite an impressive figure, but it seems no musical taste.  A problem when she is meant to sound the charge for battle!  Getting lots of recruits may mean she can return to the battlezone!</Text>\r\n<Branch Node=\"7\">Thats all I need to know!</Branch>\r\n<Branch Node=\"5\">The Terrans?</Branch>\r\n<Branch Node=\"6\">The Jenquai?</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>The representive for the Terran Alliance can be found in the main lobby of Earth Station.  Javier Domingue wants to prove himself to the hierachy, and be a merchant force to be wary of.  Recruiting you means he will be able to climb the ranks.</Text>\r\n<Branch Node=\"7\">Thats all I need to know!</Branch>\r\n<Branch Node=\"4\">The Progens?</Branch>\r\n<Branch Node=\"6\">The Jenquai?</Branch>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n<Text>There is no Jenquai representive as they are not directly battling here, but this doesn\'t matter as some Progen have chosen the Terran Alliance side and some Terrans have chosen the Progen Combine side.</Text>\r\n<Branch Node=\"7\">That\'s all I need to know.</Branch>\r\n<Branch Node=\"4\">The Progens?</Branch>\r\n<Branch Node=\"5\">The Jenquai?</Branch>\r\n</Tree>\r\n<Tree Node=\"7\">\r\n<Text>Speak to Esther McCabe in the main trade hall when you are ready to accept your use once only Draft Card ID.</Text>\r\n<Branch Node=\"8\">Ok, I am ready to be a raw recruit.</Branch>\r\n<Branch Node=\"2\">Can you repeat what is happening here?</Branch>\r\n<Branch Node=\"10\">I refuse to join this pointless war, may they both boil in the vacuum of space.</Branch>\r\n</Tree>\r\n<Tree Node=\"8\">\r\n<Text>See you soon, @name.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"9\">\r\n<Text>Neither race has their time for you.  This mission has been removed from your log!</Text>\r\n<Flags>3</Flags>\r\n</Tree>\r\n<Tree Node=\"10\">\r\n<Text>Are you sure?\r\n\r\nIf you select this option then you will NEVER be able to do missions in the warzone.  This is your final warning.</Text>\r\n<Branch Node=\"8\">I made a mistake, I will get the draft ID card.</Branch>\r\n<Branch Node=\"9\">I will not complain about missing this zone.</Branch>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Esther McCabe (Net7 Saturn) has a Draft Card ID! for you to present to either Signifier Tubicines on Arx Magister (Mars) or Javier Domingue on Earth Station (Earth).  </Description>\r\n<Completion ID=\"1\">56</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Here is the Draft Card ID.</Text>\r\n<Branch Node=\"2\">Thank You.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>No thank you, another commission!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">6177</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'A Choice To Be Made [All Races v2.0]', '56', '0', '0');
INSERT INTO `missions` VALUES ('399', '<Mission ID=\"399\" forfeitable=\"1\" time=\"0\">\r\n<Name>The Progen Combine Wants You!!</Name>\r\n<Summary>Signifier Tubicines (Arx Magister, Mars) wants to recruit you for the Progen Combine.  Are you interested?</Summary>\r\n<Condition ID=\"10\">398</Condition>\r\n<Condition ID=\"9\" Flags=\"6177\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"13\" Count=\"1\">6177</Completion>\r\n<Completion ID=\"1\">642</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome @name.\r\n\r\nAre you here to be recruited for the Progen Combine?  Select us and we will give you 1500 Progen Combine Faction, enough to enter our stargate and dock at the ECS Bremen.</Text>\r\n<Branch Node=\"2\">I select Progen Combine.</Branch>\r\n<Branch Node=\"3\">I do not want to choose now.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Speak to me again to confirm your choice.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Speak to the Terran Turncoats if you want to, but remember we are going to win this war!</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>You have selected the Progen Combine as your selected Faction.  Confirm it with the Signifier Tubicines to unlock Progen Combine supply missions and enter the combat zone.</Description>\r\n<Completion ID=\"13\" Count=\"1\">6177</Completion>\r\n<Completion ID=\"2\" Count=\"1\">6177</Completion>\r\n<Completion ID=\"1\">642</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hail Mercenary!\r\nWelcome to the Fleet!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"27\">1500</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'The Progen Combine Wants You!!', '642', '0', '0');
INSERT INTO `missions` VALUES ('400', '<Mission ID=\"400\" forfeitable=\"1\" time=\"0\">\r\n<Name>The Terran Alliance Wants You!!</Name>\r\n<Summary>Javier Domingue (Earth Station, Earth) wants to recruit you for the Terran Alliance.  Are you interested?</Summary>\r\n<Condition ID=\"10\">398</Condition>\r\n<Condition ID=\"9\" Flags=\"6177\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"13\" Count=\"1\">6177</Completion>\r\n<Completion ID=\"1\">29</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome @name.\r\n\r\nAre you here to be recruited for the Terran Alliance?  Select us and we will give you 1500 Terran Alliance Faction, enough to enter our stargate and dock at the ECS Bremen.</Text>\r\n<Branch Node=\"2\">I select Terran Alliance.</Branch>\r\n<Branch Node=\"3\">I do not want to choose now.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Speak to me again to confirm your choice.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Speak to the Progen Scum if you want to, but remember we are going to win this war!</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>You have selected the Terran Alliance as your selected Faction.  Confirm it with the Javier Domingue to unlock Terran Alliance supply missions and enter the combat zone.</Description>\r\n<Completion ID=\"13\" Count=\"1\">6177</Completion>\r\n<Completion ID=\"2\" Count=\"1\">6177</Completion>\r\n<Completion ID=\"1\">29</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Great!\r\nWelcome to the Corp!\r\n\r\nFind LaMotte on Inverness Down to obtain further missions.</Text>\r\n<Branch Node=\"2\">Will do.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Welcome aboard.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"5\" Flags=\"28\">1500</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'The Terran Alliance Wants You!!', '29', '0', '0');
INSERT INTO `missions` VALUES ('401', '<Mission ID=\"401\" forfeitable=\"1\" time=\"0\">\r\n<Name>RP level 30 hull upgrade</Name>\r\n<Summary>1</Summary>\r\n<Condition ID=\"1\">150</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">100</Completion>\r\n<Completion ID=\"23\" Text=\"TECL_test2\">1</Completion>\r\n<Tree Node=\"1\">\r\n<Text>test</Text>\r\n<Branch Node=\"2\">ok</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>test2</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>a</Description>\r\n<Completion ID=\"1\">100</Completion>\r\n<Tree Node=\"1\">\r\n<Text>test3</Text>\r\n<Branch Node=\"2\">go</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>test4</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n<Reward ID=\"12\">TECL_test</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>re</Description>\r\n<Completion ID=\"1\">100</Completion>\r\n</Stage>\r\n</Mission>\r\n', 'RP level 30 hull upgrade', '100', '0', '100');
INSERT INTO `missions` VALUES ('402', '<Mission ID=\"402\" forfeitable=\"1\" time=\"0\">\r\n<Name>Rp level 50 hull upgrade</Name>\r\n<Summary>2</Summary>\r\n<Condition ID=\"5\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">99</Completion>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>2</Description>\r\n<Completion ID=\"1\">99</Completion>\r\n</Stage>\r\n</Mission>\r\n', 'Rp level 50 hull upgrade', '99', '0', '100');
INSERT INTO `missions` VALUES ('403', '<Mission ID=\"403\" forfeitable=\"1\" time=\"0\">\r\n<Name>RP level 75 hull upgrade</Name>\r\n<Summary>3</Summary>\r\n<Condition ID=\"5\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">99</Completion>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>3</Description>\r\n<Completion ID=\"1\">99</Completion>\r\n</Stage>\r\n</Mission>\r\n', 'RP level 75 hull upgrade', '99', '0', '100');
INSERT INTO `missions` VALUES ('404', '<Mission ID=\"404\" forfeitable=\"1\" time=\"0\">\r\n<Name>RP level 100 hull upgrade</Name>\r\n<Summary>4</Summary>\r\n<Condition ID=\"5\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">99</Completion>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>4</Description>\r\n<Completion ID=\"1\">99</Completion>\r\n</Stage>\r\n</Mission>\r\n', 'RP level 100 hull upgrade', '99', '0', '100');
INSERT INTO `missions` VALUES ('405', '<Mission ID=\"405\" forfeitable=\"1\" time=\"0\">\r\n<Name>RP level 135 hull upgrade</Name>\r\n<Summary>5</Summary>\r\n<Condition ID=\"5\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">99</Completion>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>5</Description>\r\n<Completion ID=\"1\">99</Completion>\r\n</Stage>\r\n</Mission>\r\n', 'RP level 135 hull upgrade', '99', '0', '100');
INSERT INTO `missions` VALUES ('406', '<Mission ID=\"406\" forfeitable=\"1\" time=\"0\">\r\n<Name>Cornering the Market</Name>\r\n<Summary>Ferry a shipment of gases to the refinery, and take the refined product back for export.</Summary>\r\n<Condition ID=\"4\">10</Condition>\r\n<Condition ID=\"1\">30</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"5\">0</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">624</Completion>\r\n<Completion ID=\"21\">12</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Tradesman, we need you for courier duty. High pay, high risk.</Text>\r\n<Branch Node=\"2\">Alright, tell me more.</Branch>\r\n<Branch Node=\"5\">I\'d rather retire with all my body parts intact, sorry.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Alright, it\'s a straightforward courier mission. We\'ll be loading some unrefined gases from the planetary clouds onto your ship. You are to proceed to Spectre Processing Station, in low orbit around Chandilar Planet. Deliver the gases, wait for them to refine it all, then take the products back to me for export shipping.\r\n</Text>\r\n<Branch Node=\"3\">So what\'s the risk?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>The station is in the middle of a gravitic anomaly, imperative for efficient refining operations. Warp travel is difficult or impossible within 20K of that station, and we\'ve had reports of piracy within the anomaly itself. I\'d suggest bringing an escort along or travelling in numbers. You\'ll be paid appropriately upon completion of duties, but you\'ll also take on full liability for lost cargo.</Text>\r\n<Branch Node=\"4\">Alright, but I expect to be paid in full.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>You will be.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Suit yourself. Come back if you reconsider.</Text>\r\n<Flags>3</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Take the unrefined gases to Spectre Refinery for processing.</Description>\r\n<Completion ID=\"19\">15844</Completion>\r\n<Completion ID=\"13\" Count=\"12\">5899</Completion>\r\n<Completion ID=\"2\" Count=\"12\">5899</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Approaching ship, please state identity and purpose of visit.</Text>\r\n<Branch Node=\"2\">InfinitiCorp Tradesman, I have gases that need to be refined.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Okay, we\'ll transport them now. Please wait.</Text>\r\n<Branch Node=\"3\">...</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Processing.</Text>\r\n<Branch Node=\"4\">...</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Okay, here you go.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Return safely to Dispatcher Sonus with the refined product.</Description>\r\n<Completion ID=\"13\" Count=\"6\">4016</Completion>\r\n<Completion ID=\"2\" Count=\"6\">4016</Completion>\r\n<Tree Node=\"1\">\r\n<Text>The refined gases, good. Here\'s the agreed upon payment. Come back if you want more work.</Text>\r\n<Branch Node=\"2\">Excellent. Perhaps I will.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Good, good.</Text>\r\n<Flags Data=\"-2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"4\">1500</Reward>\r\n<Reward ID=\"1\">20000</Reward>\r\n<Reward ID=\"5\" Flags=\"11\">10</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Cornering the Market', '624', '0', '30');
INSERT INTO `missions` VALUES ('407', '<Mission ID=\"407\" forfeitable=\"1\" time=\"0\">\r\n<Name>Economic Superiority</Name>\r\n<Summary>Transport unrefined gases to Spectre Refinery, wait for the refining process to complete, and take the results back to Zook Station for later shipping.</Summary>\r\n<Condition ID=\"4\">10</Condition>\r\n<Condition ID=\"1\">30</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">625</Completion>\r\n<Completion ID=\"21\">12</Completion>\r\n<Tree Node=\"1\">\r\n<Text>We have courier duties to fill. There\'s danger involved, you in?</Text>\r\n<Branch Node=\"2\">Sure, why not?</Branch>\r\n<Branch Node=\"4\">I\'d rather not have to get called forward, if you know what I mean.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>We\'ll be loading some unrefined gases into your cargo bay. Go to the Spectre Processing Station and deliver them for refining. Once the refining process is complete, return here with the cargo. Be careful, you need to pass through a gravity well and we\'ve gotten confirmed reports of piracy there. You will be paid on route completion.</Text>\r\n<Branch Node=\"3\">Understood.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Make sure to get Centuriata escort if you don\'t think you can handle trouble yourself.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Pfft. Return to me when you grow a spine.</Text>\r\n<Flags>3</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver your cargo of Raw Chandilar Gases to Spectre Refinery (Chandilar, Epsilon Eridani). Watch for potentially hostile ships within the Spectre gravity well. </Description>\r\n<Completion ID=\"13\" Count=\"12\">5899</Completion>\r\n<Completion ID=\"18\">15844</Completion>\r\n<Completion ID=\"2\" Count=\"12\">5899</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Approaching ship, please state identity and purpose of visit.</Text>\r\n<Branch Node=\"2\">Progen Privateer. I have gases that need to be refined.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Alright, we\'ll transport them now. Please wait.</Text>\r\n<Branch Node=\"3\">...</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Processing.</Text>\r\n<Branch Node=\"4\">...</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Okay, here you go.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Return safely to Varo with the refined product.</Description>\r\n<Completion ID=\"1\">625</Completion>\r\n<Completion ID=\"13\" Count=\"6\">4016</Completion>\r\n<Completion ID=\"2\" Count=\"6\">4016</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Good work. Here\'s your pay. return to me if you want to do another run. </Text>\r\n<Branch Node=\"2\">Will do.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>...</Text>\r\n<Flags Data=\"-2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"4\">1500</Reward>\r\n<Reward ID=\"1\">20000</Reward>\r\n<Reward ID=\"5\" Flags=\"5\">10</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Economic Superiority', '625', '0', '30');
INSERT INTO `missions` VALUES ('408', '<Mission ID=\"408\" forfeitable=\"1\" time=\"0\">\r\n<Name>Resource Preservation</Name>\r\n<Summary>Carry several crates of Raw Chandilar Gases to Spectre Refinery, wait for the refining process to complete, and bring the Refined Chandilar Gases crates back to Zook Station (Chandilar, Epsilon Eridani) for later shipping.</Summary>\r\n<Condition ID=\"4\">10</Condition>\r\n<Condition ID=\"1\">30</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"5\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"21\">12</Completion>\r\n<Completion ID=\"1\">626</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Oh, hello. Are you free for courier duty? It might be dangerous.</Text>\r\n<Branch Node=\"2\">Sure, what\'s the job?</Branch>\r\n<Branch Node=\"4\">I don\'t feel I\'m ready for such a mission yet.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>We need some unrefined gases brought to the Spectre refinery. You\'ll have to travel through the gravitic anomaly, and there\'s pirates patrolling in there. Once you reach the refinery, have them process your cargo and return the finished product to me here.</Text>\r\n<Branch Node=\"3\">I\'ll see what I can do.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Have the Shinwa assign you escort if you\'re worried.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>When you are, return here. Safe journey.</Text>\r\n<Flags>3</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n<Reward ID=\"6\">5899</Reward>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Deliver your cargo of Raw Chandilar Gases to Spectre Refinery (Chandilar, Epsilon Eridani). Watch for potentially hostile ships within the Spectre gravity well. </Description>\r\n<Completion ID=\"18\">15844</Completion>\r\n<Completion ID=\"13\" Count=\"12\">5899</Completion>\r\n<Completion ID=\"2\" Count=\"12\">5899</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Approaching ship, please state identity and purpose of visit.</Text>\r\n<Branch Node=\"2\">Sharim. I have gases that need to be refined.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Ah, welcome. We\'ll transport them now. Please wait.</Text>\r\n<Branch Node=\"3\">...</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Processing...</Text>\r\n<Branch Node=\"4\">...</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Okay, here you go.</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n<Reward ID=\"6\">4016</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Return safely to Kiana with the refined product.</Description>\r\n<Completion ID=\"2\" Count=\"6\">4016</Completion>\r\n<Completion ID=\"1\">626</Completion>\r\n<Completion ID=\"13\" Count=\"6\">4016</Completion>\r\n<Tree Node=\"1\">\r\n<Text>I\'m glad to see you made it back safely. Here\'s your reward for nice work done. do return to me for more courier work if you ever want it.</Text>\r\n<Branch Node=\"2\">Thank you, I will.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Great.</Text>\r\n<Flags Data=\"-2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"4\">1500</Reward>\r\n<Reward ID=\"1\">20000</Reward>\r\n<Reward ID=\"5\" Flags=\"17\">10</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Resource Preservation', '626', '0', '30');
INSERT INTO `missions` VALUES ('409', '<Mission ID=\"409\" forfeitable=\"1\" time=\"0\">\r\n<Name>Gatekeeper Memnon Station Loop</Name>\r\n<Summary>Voice conversation with Gatekeeper Memnon.</Summary>\r\n<Condition ID=\"1\">150</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">654</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome to Praetorium, at this time all Warriors are asked to be confident of their training.</Text>\r\n<Branch Node=\"2\">Why should the Warriors be confident in their training?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>We must prepare for the inevitable.</Text>\r\n<Branch Node=\"3\">An Attack? Another Gate-War?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Perhaps, but even on Praetorium we can\'t drown out the homeworlds. Every day of the week there are word-beams, letters. People want Kahn to apologise, or they demand to know what he expects to achieve by this lifestyle, small minded people who attack his views and ways of thinking.</Text>\r\n<Branch Node=\"4\">More...</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>The galaxy will soon reach the end of politics, I can\'t say i\'m sorry. I don\'t think many people are dissapointed, thanks to politics we have borders and laws.... but we also have fantasies and illusions. If we had settled Cygni the right way, Kahn would never have been exiled. And we would never have the situation we have now, but we\'ll see soon enough.</Text>\r\n<Branch Node=\"5\">Khan deserves exile, or so my superiors have claimed.</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Interesting.</Text>\r\n<Branch Node=\"6\">You do not believe our superiors?</Branch>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n<Text>They are not madmen, yet they call for wars extinction. And even doubt the validity of hand to hand combat, can you imagine in this day and age. But that\'s a debate that must keep.</Text>\r\n<Branch Node=\"7\">So... Can you give me a mission to do?</Branch>\r\n</Tree>\r\n<Tree Node=\"7\">\r\n<Text>See your class leader for a mission, I don\'t give missions here.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Gatekeeper Memnon Station Loop', '654', '0', '100');
INSERT INTO `missions` VALUES ('410', '<Mission ID=\"410\" forfeitable=\"1\" time=\"0\">\r\n<Name>Shou Tzu OMP Station Conversation [Temporary]</Name>\r\n<Summary>Voice conversation with Shou Tzu. Repeatable for the moment.</Summary>\r\n<Condition ID=\"1\">150</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">655</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hey stranger, we don\'t get many ships here or we didn\'t used anyway.</Text>\r\n<Branch Node=\"2\">I\'m looking for a mission.</Branch>\r\n<Branch Node=\"10\">You think I\'m lost?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>You should go, unless you need another demonstration. In which case, you know where to find me.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Shou Tzu OMP Station Conversation [Temporary]', '655', '0', '100');
INSERT INTO `missions` VALUES ('411', '<Mission ID=\"411\" forfeitable=\"1\" time=\"0\">\r\n<Name>Reactor Optimization for the Seeker [OFF]</Name>\r\n<Summary>Learn Reactor Optimization.</Summary>\r\n<Condition ID=\"5\">1</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"1\">1</Condition>\r\n<Condition ID=\"9\" Flags=\"2825\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">489</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Are you interested in learning how to Optimizae your Reactor output?</Text>\r\n<Branch Node=\"2\">Sounds Awesome!</Branch>\r\n<Branch Node=\"3\">No thanks.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Speak with me again.  I need to call for your ship to recieve this \"upgrade.\"</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Suit yourself.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Talk to Omaka again.</Description>\r\n<Completion ID=\"1\">489</Completion>\r\n<Tree Node=\"1\">\r\n<Text>I am ready to equip your ship with this skill.</Text>\r\n<Branch Node=\"2\">Thank you.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Take care young one.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"9\">58</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Reactor Optimization for the Seeker [OFF]', '489', '0', '60');
INSERT INTO `missions` VALUES ('413', '<Mission ID=\"413\" forfeitable=\"0\" time=\"0\">\r\n<Name>Some Funeral</Name>\r\n<Summary>Omaka needs you to scan the wreckages of his deceased students for information. A good opportunity to test your reactor optimization skill in the perils of space.</Summary>\r\n<Condition ID=\"10\">81</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">489</Completion>\r\n<Tree Node=\"1\">\r\n<Text>So you have learned how to fight, barely, but if you chose the path of the Sharim to fight, you may want to reconsider. \r\n\r\nSeekers lack the discipline and firepower of the Shinwa Defenders, but they have advantages to make up for that fact. I\'m sure somebody on the station has already preached to you about the Seeker\'s money making prowess, but they probably didn\'t tell you all the uses of having a Seeker in one\'s group.</Text>\r\n<Branch Node=\"2\">Oh? Well I guess shield recharge helps.</Branch>\r\n<Branch Node=\"3\">I think I\'ll stick to fighting alone.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>It does. As you will see, shield recharge can be vital in groups.</Text>\r\n<Branch Node=\"4\">Continue..</Branch>\r\n<Branch Node=\"5\">...</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Suit yourself... But that\'s a foolish mistake.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Don\'t you DARE tell me to get on with it! The fact that I\'m teaching you at all should mean you bowing at my feet.\r\n\r\nNow then, another helpful aspect of the Seeker is the ability to optimize your own reactor and the reactors of others. Through optimization you can increase reactor capacity and recharge rate. Unfortunately all reactors are set to reset themselves after a certain amount of time to prevent any long term damaging effects, so the effect is temporary.\r\n\r\nOptimization is extremely useful for surviving situations where your reactor is draining too fast to meet demands. As you will soon find out.</Text>\r\n<Branch Node=\"6\">Uh oh.</Branch>\r\n<Branch Node=\"8\">Or not!</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>...</Text>\r\n<Branch Node=\"4\">Continue..</Branch>\r\n<Branch Node=\"9\">...</Branch>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n<Text>Yes that\'s right. I need you to do another task for me. For some reason a few of my younger students decided to travel to the Kor Kor Asteroid Belt, a small yet dangerous field inhabited by aggressive Manes. Since you have been one of my more promising students I ask that you travel to the site of their hulks and scan them to see if there are any items of value that would be worth sending in a recovery patrol for.</Text>\r\n<Branch Node=\"7\">I\'ll help you.</Branch>\r\n<Branch Node=\"8\">Send in the patrols!</Branch>\r\n</Tree>\r\n<Tree Node=\"7\">\r\n<Text>I\'ll provide you the ability to optimize your reactor, and hopefully it will keep you from joining my earlier students..</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"8\">\r\n<Text>Some cowards never learn...</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n<Tree Node=\"9\">\r\n<Text>...</Text>\r\n<Branch Node=\"4\">Continue..</Branch>\r\n<Branch Node=\"5\">...</Branch>\r\n</Tree>\r\n<Reward ID=\"9\">43</Reward>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Head to Kor Kor Asteroid Belt and scan the Wreckage of Nan\'Jeu Gopal. If you encounter Manes, use shield recharge and reactor optimization to keep yourself alive.</Description>\r\n<Completion ID=\"12\">15959</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Scan the Wreckage of Nan\'Jeu Ranjit and prepare to warp back to the Azmundi Maru.</Description>\r\n<Completion ID=\"12\">15965</Completion>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Return to Azmundi Maru and talk to Omaka Kasinagi.</Description>\r\n<Completion ID=\"1\">489</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Now let\'s see what they had on them...</Text>\r\n<Branch Node=\"2\">This whole situation seems pretty crude.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Listen, I don\'t want to risk the lives of anyone if I don\'t have to. Except maybe your life, but that was for the sake of training.</Text>\r\n<Branch Node=\"3\">You\'re the most caring guy I know.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Sarcasm is a cowards weapon. But I am done with you for now. Achieve level 10 and talk to Kayen Silva to learn your last portion of training, cloaking. I would thank you for your efforts, but I am the teacher and think it would be more fitting if you were to thank me.</Text>\r\n<Branch Node=\"4\">Thanks master!</Branch>\r\n<Branch Node=\"5\">Forget it!</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>I hope that the next time I teach you, you will do better...</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>/smash Such impudence I did not even expect from the likes of you. Now GO!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n</Stage>\r\n</Mission>\r\n', 'Some Funeral', '489', '0', '0');
INSERT INTO `missions` VALUES ('415', '<Mission ID=\"415\" forfeitable=\"1\" time=\"0\">\r\n<Name>Scan for radiation</Name>\r\n<Summary>Scan for radiation</Summary>\r\n<Condition ID=\"1\">70</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">659</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hello @name I have a job for you and you can get 5000 Explore XP and 5000 credits for it, are you interested?</Text>\r\n<Branch Node=\"2\">sure</Branch>\r\n<Branch Node=\"3\">no thanks</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Goto Path of Fire 7 and find Aragoth Probe 1</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Shame, maybe next time</Text>\r\n<Flags>3</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Find and scan Aragoth Probe 1 (might need to retarget the nav)</Description>\r\n<Completion ID=\"15\">1647</Completion>\r\n<Completion ID=\"12\">1647</Completion>\r\n<Reward ID=\"2\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Find and scan Aragoth Probe 4</Description>\r\n<Completion ID=\"15\">1646</Completion>\r\n<Completion ID=\"12\">1646</Completion>\r\n<Reward ID=\"2\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Find and scan Aragoth Probe 3</Description>\r\n<Completion ID=\"15\">1645</Completion>\r\n<Completion ID=\"12\">1645</Completion>\r\n<Reward ID=\"2\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>Find and scan Aragoth Probe 2</Description>\r\n<Completion ID=\"15\">1644</Completion>\r\n<Completion ID=\"12\">1644</Completion>\r\n<Reward ID=\"2\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"5\">\r\n<Description>Return to Explore NPC</Description>\r\n<Completion ID=\"1\">659</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Good job @name here is your reward</Text>\r\n<Flags Data=\"-2\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"2\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Scan for radiation', '659', '0', '0');
INSERT INTO `missions` VALUES ('417', '<Mission ID=\"417\" forfeitable=\"1\" time=\"0\">\r\n<Name>A Present for You All</Name>\r\n<Summary>Ho Ho Ho. Merry X-mas! Help Old Nick gather 5 presents from his elves and he might give you a present in return.</Summary>\r\n<Condition ID=\"1\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"18\">15978</Completion>\r\n<Completion ID=\"19\">15978</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Ho Ho Ho! @name would you like a present?</Text>\r\n<Branch Node=\"2\">Of course I would like a present!</Branch>\r\n<Branch Node=\"4\">I do not take presents from strange men.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I need your help picking up 5 presents from several elves in various stations.</Text>\r\n<Branch Node=\"3\">Ok cool. Where are they?</Branch>\r\n<Branch Node=\"4\">At second thought, this is probably going to be a wild goose chase.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>The first elf will be at Net-7. After getting the present, you will be told where the second elf is. Listen carefully and hurry, @name! I have an agenda to keep and this task must be completed to help bring presents to all the little nice girls and boys throughout the universe.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Then you will get nothing this year. Enjoy your time on the naughty list!</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Get the first present from Askasleikir.</Description>\r\n<Completion ID=\"1\">664</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hello @name what can I do for you?</Text>\r\n<Branch Node=\"2\">I was sent here to get a present for Old Nick.</Branch>\r\n<Branch Node=\"5\">I don\'t know.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Errmm let me check... Oh wait...  Yes I got it! Here is the present.</Text>\r\n<Branch Node=\"3\">Thank you. Do you know where to get the second present?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Yes, it should be in Orsini Mining Platform, talk to my friend Bjugnakraekir.</Text>\r\n<Branch Node=\"4\">Bjugnakraekir? Ok, thank you.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>No problem, but hurry up. Old Nick has an agenda he has to keep!</Text>\r\n<Flags Data=\"2\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Then leave me alone, I am busy.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5220</Reward>\r\n<Reward ID=\"2\">500</Reward>\r\n<Reward ID=\"4\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Get the second present from Bjugnakraekir</Description>\r\n<Completion ID=\"1\">661</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Ho Ho Ho! @name, I been hearing you\'re here for the present to pick up for Old Nick.</Text>\r\n<Branch Node=\"2\">Yes, you are correct.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Here you go, one present for Nick. Thanks for your help!</Text>\r\n<Branch Node=\"3\">Thank you. Do you know where I have to go to next?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Yes @name, you have to go to Fenris Prime Observatory. There you will find Faldafeykir who should have the next present for you.</Text>\r\n<Flags Data=\"3\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5220</Reward>\r\n<Reward ID=\"4\">500</Reward>\r\n<Reward ID=\"2\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Talk to Faldafeykir to receive the third present.</Description>\r\n<Completion ID=\"1\">665</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome @name. How can I help you?</Text>\r\n<Branch Node=\"2\">I am here to pick up a present for Old Nick.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Hmmm I have not had word that someone was going to be here to pick up a present for him. Are you sure you\'re in the right place?</Text>\r\n<Branch Node=\"3\">Yes, I am positive.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Hold on... Let me contact him.</Text>\r\n<Branch Node=\"4\">Ok, I wait now.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Well seems I did not get the message, but you\'re right. Old Nick has sent you so here is the present.</Text>\r\n<Branch Node=\"5\">Thank you, and might I ask you a question?</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Sure @name. What is it you want to know?</Text>\r\n<Branch Node=\"6\">Where can I pick up the next present?</Branch>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n<Text>You can pick it up from Earth station from Gattathefur.</Text>\r\n<Branch Node=\"7\">Thank you very much</Branch>\r\n</Tree>\r\n<Tree Node=\"7\">\r\n<Text>Now off you go!</Text>\r\n<Flags Data=\"4\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5220</Reward>\r\n<Reward ID=\"2\">500</Reward>\r\n<Reward ID=\"4\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>Talk to Gattathefur to get the fourth present.</Description>\r\n<Completion ID=\"1\">666</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hi there @name. How are you?</Text>\r\n<Branch Node=\"2\">I am fine, thank you. How about yourself?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I am fine too, thank you for asking. What can I do for you?</Text>\r\n<Branch Node=\"3\">I am here to pick up a present for Old Nick.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Ah yes, I was waiting for you. Here you go. Good luck!</Text>\r\n<Branch Node=\"4\">Thank you.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>The final present can be received from Giljagaur at ECS Dauntless.</Text>\r\n<Flags Data=\"5\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5220</Reward>\r\n<Reward ID=\"2\">500</Reward>\r\n<Reward ID=\"4\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"5\">\r\n<Description>Get the final present from Giljagaur then return to Old Nick in Saturn.</Description>\r\n<Completion ID=\"1\">667</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hiya @name.</Text>\r\n<Branch Node=\"2\">Hello Giljagaur</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>You are here for a reason?</Text>\r\n<Branch Node=\"3\">Yes. I am here to get the final present for Old Nick.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Ah yes, the final present... here you go. Now return to Old Nick in Saturn! Better hurry and catch him before he takes off!</Text>\r\n<Flags Data=\"6\">5</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">5220</Reward>\r\n<Reward ID=\"4\">500</Reward>\r\n<Reward ID=\"2\">500</Reward>\r\n</Stage>\r\n<Stage ID=\"6\">\r\n<Description>Give Old Nick the five presents you gathered and receive your reward.</Description>\r\n<Completion ID=\"19\">15978</Completion>\r\n<Completion ID=\"13\" Count=\"5\">5220</Completion>\r\n<Completion ID=\"2\" Count=\"5\">5220</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Ho Ho Ho @name. You got all my presents?</Text>\r\n<Branch Node=\"2\">Yes Old Nick. I got them, all five.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Wonderful, any problems on the way?</Text>\r\n<Branch Node=\"3\">Not really, but an elf did not receive your message that I was coming.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Yes I heard, he contacted me... wonder why he did not get the message.</Text>\r\n<Branch Node=\"4\">Well, here are the presents.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Thank you @name. Here is something for your troubles, Ho Ho Ho! Merry Christmas!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">6178</Reward>\r\n<Reward ID=\"6\">6179</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'A Present for You All', '112', '0', '0');
INSERT INTO `missions` VALUES ('418', '<Mission ID=\"418\" forfeitable=\"1\" time=\"0\">\r\n<Name>Radiation Testing</Name>\r\n<Summary>Sai\'li Raushna is concerned with the radiation levels in Xipe Totec. Help her test the radiation as you wander to the other side of the Intzalan Line.</Summary>\r\n<Condition ID=\"1\">10</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">301</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hello. I\'m sure you have heard of the perils of this sector by now. The main problem I believe is the oni, which I have studied greatly. If you would like to know more about them we can discuss them later. Unfortunately the oni also bring many problems with them. You may not have discovered yet, but on the other side of that giant energy net is a dangerous field of radiation.</Text>\r\n<Branch Node=\"2\">I\'m definitely not going over there.</Branch>\r\n<Branch Node=\"8\">Bring it on!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Well most ships are usually able to manage the shallow depths of the outer edge. If you\'re looking to explore, the only thing that would be affected is your shields. Though if you\'re really unlucky, you might run into equipment failure and hull deterioration. Hopefully this will not be the case.</Text>\r\n<Branch Node=\"3\">Hopefully.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>As I mentioned before I am interested in tracking the progress of the oni. Since they are too dangerous to study we have to use other methods of tracking them. The safest method is to study the radiation at certain depths of the area, a study in which I am looking for volunteers.</Text>\r\n<Branch Node=\"4\">That doesn\'t sound safe.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Did I say it was safe? I said radiation gathering was the safest method of study. That doesn\'t mean you won\'t come across hardship, such as engine failure in the middle of field of manes.</Text>\r\n<Branch Node=\"5\">Sign me up!</Branch>\r\n<Branch Node=\"6\">NO, No, no, no Nooo!</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Excellent! Finally, a taker. For some reason, nobody really wants to travel to the other side of the Intzalan Line. Proceed to test the radiation at Dragon\'s Watch Alpha. I want to see if the radiation has progressed or not. And please don\'t die...</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n<Text>Fine, sheesh.. Though please come back, I\'ll probably still be looking for a volunteer.</Text>\r\n<Branch Node=\"7\">And you wonder why?</Branch>\r\n</Tree>\r\n<Tree Node=\"7\">\r\n<Text>Yes, I thought adventurers were supposed to be, well, adventurous.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n<Tree Node=\"8\">\r\n<Text>Well that\'s a positive spirit, but I\'m afraid you won\'t fit in around here. The good spirited ones are the dead ones. But I suppose you can prove me wrong. Would you like to volunteer?</Text>\r\n<Branch Node=\"3\">Sure!</Branch>\r\n<Branch Node=\"9\">I am needed elsewhere.</Branch>\r\n</Tree>\r\n<Tree Node=\"9\">\r\n<Text>Well when you\'re not busy, I\'m always looking for volunteers, that is, until one actually signs up. I mean... you\'re missing out on a golden opportunity.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Find Dragon\'s Watch Alpha in Xipe Totec, Sirius System.</Description>\r\n<Completion ID=\"15\">1496</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>You have collected a radiation sample. Return it to Sai\'li Raushna in Prasad Station.</Description>\r\n<Completion ID=\"1\">301</Completion>\r\n<Tree Node=\"1\">\r\n<Text>You... return!</Text>\r\n<Branch Node=\"2\">You sound surprised.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>My face is simply radiated over this sample. Ahaha, you\'ve done well.</Text>\r\n<Branch Node=\"3\">It wasn\'t as dangerous as you made it sound.</Branch>\r\n<Branch Node=\"4\">You nearly killed me!</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>Very well, so you got lucky, but your luck will eventually run out. Heed this warning. As indicated by the radiation, the great oni\'s power is increasing. Stay away from the depths of the radiation field and you will escape this sector with your hide.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>I\'m sorry, but if it makes you feel any better, the radiation has increased over the course of the past two years. The great oni\'s power is growing.</Text>\r\n<Branch Node=\"5\">How is that supposed to make me feel better?</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>It makes my life more interesting, and I\'m sure there will be more opportunities to volunteer in the future. Thanks for your help and enjoy your reward.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"2\">6000</Reward>\r\n<Reward ID=\"1\">15000</Reward>\r\n<Reward ID=\"5\" Flags=\"16\">750</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Radiation Testing', '301', '0', '0');
INSERT INTO `missions` VALUES ('419', '<Mission ID=\"419\" forfeitable=\"1\" time=\"0\">\r\n<Name>The Rescue</Name>\r\n<Summary>A Shinwa has requested emergency assistance after wandering past the Intalzan Line. Find and rescue the ship.</Summary>\r\n<Condition ID=\"1\">101</Condition>\r\n<Condition ID=\"5\">1</Condition>\r\n<Condition ID=\"10\">418</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">301</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Just in time! @name, I urgently require you as a volunteer.</Text>\r\n<Branch Node=\"2\">Happy to help.</Branch>\r\n<Branch Node=\"3\">Not interested.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>A Shinwa wandered out beyond the Intzalan Line and has since sent out an S.O.S. I don\'t know what has happened to him or why he has wandered out there, but I do know that he needs rescue. Please hurry.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>/point The Shinwa are in need and you must help. When you are called, do not avoid it!</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>S.O.S. was submitted from Dragon\'s Watch Alpha.</Description>\r\n<Completion ID=\"15\">1496</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Target was heading for Dragon\'s Watch Beta.</Description>\r\n<Completion ID=\"15\">1498</Completion>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>New S.O.S. received. Coordinates: -8.60, 19.05, 0.</Description>\r\n<Completion ID=\"4\" Count=\"1\">485</Completion>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>Return to Sai\'li Raushna on Prasad Station.</Description>\r\n<Completion ID=\"1\">301</Completion>\r\n<Tree Node=\"1\">\r\n<Text>@name, why did you not bring back the missing Shinwa? Were you unable to find him?</Text>\r\n<Branch Node=\"2\">I... had to kill him.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>The oni take yet another life. For years I found the oni fascinating creatures, but since you volunteered last, they have only grown in power. The Shinwa pilot had been patrolling the Intalzan line and was most likely lured into madness by the great oni, a terrible and painful fate I am sure it was.</Text>\r\n<Branch Node=\"3\">What do we do now?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>I really don\'t know @name, but I have remorsefully put you in a terrible situation. I didn\'t tell you when I signed you up, but the Shinwa you were sent to rescue was the nephew of our great leader, Du\'Shao Silva. I\'m sure Silva will be crippled by the news as he had a close relationship with his nephew. Since you were the one who witnessed his demise, please relay what happened to Silva. It may be difficult for him to hear, but it is necessary.</Text>\r\n<Flags Data=\"5\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"5\">\r\n<Description>Tell Du\'Shao Silva of his nephew\'s plight. Silva resides at Yasuragi on Planet Swooping Eagle.</Description>\r\n<Completion ID=\"1\">355</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Welcome. I am Silva and this is Yasuragi. What are you here for? You look to me nervous.</Text>\r\n<Branch Node=\"2\">I bring bad news. Your nephew has fallen.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>/no My nephew? I had hoped this day would never come. I always knew Xipe Totec was a dangerous place for any Shinwa, but we must do our duty. He was leading by example. Even I looked up to him in courage. Tell me, what led him to his end?</Text>\r\n<Branch Node=\"3\">...I did.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>What outrage is this? For what reason did you silence my nephew?</Text>\r\n<Branch Node=\"4\">He was driven mad by the oni. I was only defending myself.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>...Unforgiving is fate at times. To fall to one\'s friends is not the warrior\'s way, but I understand my nephew had little choice.\r\n\r\n...I will be grateful for you for your services one day, but not today. It is a somber day for me.</Text>\r\n<Flags Data=\"6\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"6\">\r\n<Description>Return to Sai\'li Raushna.</Description>\r\n<Completion ID=\"1\">301</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Thank you for volunteering for this.. difficult job.</Text>\r\n<Branch Node=\"2\">When duty calls, it calls all Jenquai.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Thank you for answering the call and I hope I can call upon you in the future yet again.\r\n\r\nI reward you for your efforts, but do not forget about this place. To preserve our place in this sector, our bastion against the oni must not fall.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"6\">2271</Reward>\r\n<Reward ID=\"1\">75000</Reward>\r\n<Reward ID=\"3\">8000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'The Rescue', '301', '0', '0');
INSERT INTO `missions` VALUES ('420', '<Mission ID=\"420\" forfeitable=\"1\" time=\"0\">\r\n<Name>How Repulsive!! [Version 1.0.S]</Name>\r\n<Summary>After completing Prospect II, speak to Fet Rastain to learn another skill.</Summary>\r\n<Condition ID=\"10\">264</Condition>\r\n<Condition ID=\"6\">2</Condition>\r\n<Condition ID=\"5\">2</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">90</Completion>\r\n<Tree Node=\"1\">\r\n<Text>I tell you @name, that was some mighty looking fine copper you supplied me.</Text>\r\n<Branch Node=\"2\">Great, is there anything I can do for you?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Actually, @profession, there\'s something I can do for you!\r\n\r\nWe\'ve developed a skill called Repulsor Field that is very useful to Sentinels, once activated on yourself or others, the Repulsor Field can divert incoming fire back to enemies.\r\n\r\nDo you want to learn it?</Text>\r\n<Branch Node=\"3\">Yes I do.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>The thing is, your ship is not correctly designed to handle the Repulsor Field\'s effects.  We need you to go and mine some Magnetite Ore so we can modify your ship to handle the energies.\r\n\r\n\r\n\r\nAs we speak, the Shipyard in Primus is backdated with many vessels being \'modified\'.  </Text>\r\n<Branch Node=\"4\">How much will I need?</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Return to me with an amount of magnetite you have prospected to match your hull strength.  Don\'t you know it?  Next time you are in space, hover your mouse over the red bar.  That is your hull.  If its not 13 then someone has made a mistake...\r\n\r\n\r\n.. or something has started to eat you!</Text>\r\n<Branch Node=\"5\">Ok, I\'m on my way.</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Don\'t forget, @race.\r\n13 units of magnetite ore that you have prospected.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Prospect enough magnetite ore to cover your hull.</Description>\r\n<Completion ID=\"8\">2845</Completion>\r\n</Stage>\r\n<Stage ID=\"2\">\r\n<Description>Return to [Fet Rastian] to allow the magnetite cover to be applied to your hull.</Description>\r\n<Completion ID=\"13\" Count=\"13\">2845</Completion>\r\n<Completion ID=\"2\" Count=\"13\">2845</Completion>\r\n<Completion ID=\"1\">90</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Quick, bring the magnetite ore here!\r\n\r\nLet me see it.</Text>\r\n<Branch Node=\"2\">Here you go.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>RECLAIMER!!!\r\nCome here.\r\n\r\nWhere is he?  Ah there you are.\r\nTake this ore and use your plasma forge apply it to the hull coating.\r\n</Text>\r\n<Branch Node=\"3\">How long will that take?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>It shoudn\'t be that long, but we need the covering to initialise in battle before it can be used.  You don\'t want a leaky hull do you!</Text>\r\n<Branch Node=\"4\">Not without means of patching the hull, I don\'t!</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Go to Debris Area Beta and engage in combat with a [Swarming Mane CL1].  This should fix your hull up nicely as your shield attempts to counter the mane\'s attacks.  \r\n\r\n\r\n\r\nI\'ll then send you the code to unlock the Repulsor Field skill.  While you are there you may as well apply it to yourself and slay another [Swarming Mane CL1].  Hopefully you will notice some difference.\r\n\r\nReturn to me when you are done.</Text>\r\n<Branch Node=\"5\">Kill then apply skill then kill and return.  OK.</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Happy hunting!</Text>\r\n<Flags Data=\"3\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"3\">\r\n<Description>Go and kill a Swarming Mane in Debris Area Beta [CL 1]</Description>\r\n<Completion ID=\"4\" Count=\"1\">1399</Completion>\r\n<Reward ID=\"9\">48</Reward>\r\n</Stage>\r\n<Stage ID=\"4\">\r\n<Description>After putting points into Repulsor Field and activating it on yourself, see the difference by killing another Swarming Mane [CL 1]</Description>\r\n<Completion ID=\"4\" Count=\"1\">1399</Completion>\r\n</Stage>\r\n<Stage ID=\"5\">\r\n<Description>Return to Fet Rastian.</Description>\r\n<Completion ID=\"1\">90</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Well, @name how was that!</Text>\r\n<Branch Node=\"2\">Fantastic!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>I know.\r\nAnd at higher skill levels you can apply it to others.  Don\'t worry about having to supply more magnetite ore, we\'ve developed a Progen Hull Alloy which contains the magnetite and will be used in all future hull upgrades.</Text>\r\n<Branch Node=\"3\">Excellent!</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>What are you waiting for?\r\nGo and find something to do or someone who wants you to do something!</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"3\">5000</Reward>\r\n<Reward ID=\"1\">5000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'How Repulsive!! [Version 1.0.S]', '90', '0', '0');
INSERT INTO `missions` VALUES ('422', '<Mission ID=\"422\" forfeitable=\"1\" time=\"0\" jobcategory=\"2\">\r\n<Name>Satellite Deployment</Name>\r\n<Summary>Deploy the satellite as requested.</Summary>\r\n<Condition ID=\"1\">0</Condition>\r\n<Stage ID=\"0\">\r\n<Reward ID=\"6\">6041</Reward>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Take the Satellite to @object in @sector, and deploy the satellite using the control.</Description>\r\n<Completion ID=\"24\">6041</Completion>\r\n<Reward ID=\"2\">2500</Reward>\r\n<Reward ID=\"4\">1500</Reward>\r\n</Stage>\r\n</Mission>', 'Deploy Satellite', '301', '1', '0');
INSERT INTO `missions` VALUES ('423', '<Mission ID=\"423\" forfeitable=\"1\" time=\"0\">\r\n<Name>Temporary Fold Space Mission</Name>\r\n<Summary>Temporary mission to acquire the fold space skill</Summary>\r\n<Condition ID=\"1\">8</Condition>\r\n<Condition ID=\"5\">1</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">617</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hello @name.</Text>\r\n<Branch Node=\"2\">Can you teach me fold space?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>If you still need to learn, I suppose. Talk to me again to be trained.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Talk to Lydia Haruka to be trained.</Description>\r\n<Completion ID=\"1\">617</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Fold space is a skill designed to teleport yourself, friends, and enemies. By teleporting you gain a tactical advantage over enemies.</Text>\r\n<Branch Node=\"2\">I am ready to learn.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>You now know fold space. Use it well.</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"9\">24</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Temporary Fold Space Mission', '617', '0', '0');
INSERT INTO `missions` VALUES ('424', '<Mission ID=\"424\" forfeitable=\"1\" time=\"0\">\r\n<Name>Where is my Reactor Skill?</Name>\r\n<Summary>A temporary mission till the other one is fixed.</Summary>\r\n<Condition ID=\"5\">1</Condition>\r\n<Condition ID=\"6\">1</Condition>\r\n<Condition ID=\"1\">60</Condition>\r\n<Stage ID=\"0\">\r\n<Completion ID=\"1\">671</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Hey there partner.  Could I ask ye a big favor?</Text>\r\n<Branch Node=\"2\">What is it?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n<Text>Well this fancy smancy lady-gal with blonde hair left me some work orders to fix this here terminal up, real good if you know what I mean. </Text>\r\n<Branch Node=\"3\">This is not another boring \"please get me blah\" now is it?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n<Text>No sir\'e do.  See, I need to special order tool from Infinit-tity Corp.  But being a blue collered worker these days, it is hard to make enough credits to afford the tools I need.  This tool costs Thirty-Five Thousand credits.  Out of my price range, if you get what i mean.</Text>\r\n<Branch Node=\"4\">If I help you, what is in it for me?</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n<Text>Well, see that Blonde Lady-gal left this here book on the counter of the bar.  I\'ll give it to you as payment.  *shows a textbook titled \"How to Build Reactors, for Dummies\"*</Text>\r\n<Branch Node=\"5\">Forget it, I am not interested.</Branch>\r\n<Branch Node=\"6\">Sure thing pops.  Be back in a jippy.</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n<Text>Well then, see you around the station.</Text>\r\n<Flags>2</Flags>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n<Text>When you bring me those credits, I\'ll gladly hand this book over to you.  Of course, the longer you delay, the longer this job is going to take me.</Text>\r\n<Flags Data=\"1\">5</Flags>\r\n</Tree>\r\n</Stage>\r\n<Stage ID=\"1\">\r\n<Description>Bring 35,000 credits back to the Getco Mechanic.</Description>\r\n<Completion ID=\"1\">671</Completion>\r\n<Completion ID=\"14\">35000</Completion>\r\n<Tree Node=\"1\">\r\n<Text>Thank yer for the credits.  This should let me buy the parts I need to fix her up real good. *wink*</Text>\r\n<Flags>6</Flags>\r\n</Tree>\r\n<Reward ID=\"9\">8</Reward>\r\n<Reward ID=\"4\">10000</Reward>\r\n</Stage>\r\n</Mission>\r\n', 'Where is my Reactor Skill?', '671', '0', '0');
