INSERT INTO `sectors` VALUES ('3705', 'Ardus', '-155000', '-155000', '-50000', '310000', '310000', '50000', '50000', '50000', '50000', '100000', '100000', '0', '0', '0', '0', '0', '0', '1.22137', '1', '0', '9.33033', '9.33033', '57', 'COMPUTER: We have entered Ardus Sector (Aquitaine System).', '19/05/2007\r\nDid some work here-->Feniks.\r\nBackground/Skybox = ID 57 \r\nAdded astroids. But it seems they won`t show up as a navigation beacon, and not sure if it are moons or real astroids what they used in live game, so I stop adding astroids till I know more.\r\n I will look here later, if you want to see some go to Ardus Delta. \r\nHave to look at some moons\r\n-----------------------------------------', '9', '0', '0', null, '0', '0', '9', null);
