INSERT INTO `skill_levels` VALUES ('0', '12', '3', 'Reduces the amount of time required to cloak to 5 seconds, and enables the Advanced Cloak ability.');
INSERT INTO `skill_levels` VALUES ('1', '37', '3', 'Increases success chances and enables the Advanced Power Down ability.'), ('2', '37', '5', 'Increases success chances and enables the Advanced Power Down 2 ability.'), ('3', '37', '6', 'Increases success chances and enables the Advanced Power Down 3 ability.'), ('4', '37', '7', 'Increases success chances and enables the Advanced Power Down 4 ability.'), ('6', '22', '1', 'Enables the Anger ability.'), ('7', '22', '6', 'Improves effect power, increases range to 6250 units, and enables the Anger Group ability.'), ('8', '47', '6', 'Improves equipment repair rate, increases range to 3750 units, and enables the Area Equipment Repair ability.'), ('9', '27', '6', 'Increases the rate of hull repair, extends range to 3750 units, and enables the Area Hull Repair ability.'), ('10', '25', '7', 'Improves ability powers, increases range to 6500 units, and enables the Area Immobilization Field ability.'), ('11', '33', '6', 'Improves ability powers, increases range to 3750 units, and enables the Area Intimidation ability.'), ('12', '25', '6', 'Improves ability powers, increases range to 6250 units, and enables the Area Mass Field ability.'), ('13', '26', '7', 'Improves hacking success rates, extends range to 2500 units, and enables the Area Multi-Hack ability.'), ('14', '46', '6', 'Enables the Area Shield Recharge ability and increases range to 3750 units.'), ('15', '2', '7', 'Improves success rates, increases range to 6500 units, and enables the Area Soothe ability.'), ('16', '26', '6', 'Improves hacking success rates, extends range to 2250 units, and enables the Area System Hack ability.'), ('17', '24', '7', 'Increases teleportation range to 6800 units and enables the Area Teleport ability.'), ('18', '33', '7', 'Improves ability powers, increases range to 4000 units, and enables the Area Terrify ability.'), ('19', '15', '5', 'Enables the Asteroid Belt Beta Gate ability.'), ('20', '2', '1', 'Enables the Befriend ability.'), ('21', '3', '7', 'Attempts to temporarily disable a single weapon possessed by an organic target, increases duration, and extends range to 2500 units. Entities with a single active weapon are more difficult to effect.'), ('22', '3', '1', 'Reduces the firing rate of all weapons possessed by an organic target.'), ('23', '3', '5', 'Reduces the firing rate of all weapons possessed by organic entities within the area of effect, increases duration, and extends range to 2000 units.'), ('24', '3', '3', 'Reduces the firing rate of all weapons possessed by an organic target, lowers the probability that the target will use skills it possesses, increases duration, and extends range to 1500 units.'), ('25', '3', '6', 'Reduces the firing rate of all weapons possessed by organic entities within the area of effect, lowers the probability that the entities will use skills they possess, increases duration, and extends range to 2250 units.'), ('26', '15', '6', 'Enables the Carpenter Gate ability.'), ('27', '22', '3', 'Improves effect power, increases range to 5500 units, and enables the Cause Aggression ability.'), ('28', '12', '1', 'Enables the Cloak ability.');
