INSERT INTO `skill_levels` VALUES ('39', '19', '3', 'Improves amount of drain on a single target, converts a percentage of that into energy for the player, and extends range to 1500 units.');
INSERT INTO `skill_levels` VALUES ('40', '19', '6', 'Improves amount of energy drain in a spherical area of effect of 1500 units surrounding the player, converts a percentage of that into energy for the player, and extends range to 2250 units.');
