INSERT INTO `skill_levels` VALUES ('50', '48', '6', 'Generates feedback damage when skill user is struck by affected damage types, increases maximum feedback amount, and duration. Ability may be applied to skill user or other characters.');
INSERT INTO `skill_levels` VALUES ('51', '12', '7', 'Enables the Group Cloak ability.');
INSERT INTO `skill_levels` VALUES ('52', '53', '5', 'Improves amount of shield drain on a single target, converts a percentage of that into energy for the player and their group, and extends range to 2000 units.');
