INSERT INTO `skills` VALUES ('0', 'Afterburn', 'The Afterburn skill is used to greatly increase movement speed for short durations.', '1', 'Combat', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '7', '-1'), ('1', 'Beam Weapon', 'Allows use of beam weapons of a level equal to or below the skill level, and increases damage with beam weapons by +25% per level.', '0', 'Combat', '8', '8', '8', '9', '9', '9', '8', '8', '8'), ('2', 'Befriend', 'Befriend abilities can be used to make NPCs friendly or keep them from attacking.', '1', 'Trade', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '7'), ('3', 'Biorepression', 'Biorepression abilities can be used to slow the rate of fire, reduce skill usage, and temporarily disable the weapons of organic targets.', '1', 'Combat', '-1', '-1', '-1', '-1', '-1', '-1', '7', '-1', '-1'), ('4', 'Build Components', 'Allows analysis and manufacture of component items of a level equal to or below the skill level.', '0', 'Trade', '-1', '-1', '7', '-1', '-1', '7', '-1', '-1', '7'), ('5', 'Build Devices', 'Allows analysis and manufacture of devices of a level equal to or below the skill level, and increases the quality of manufactured devices.', '0', 'Trade', '-1', '7', '-1', '7', '7', '7', '-1', '7', '7');
INSERT INTO `skills` VALUES ('6', 'Build Engines', 'Allows analysis and manufacture of engines of a level equal to or below the skill level, and increases the quality of manufactured engines.', '0', 'Trade', '-1', '-1', '-1', '-1', '-1', '7', '7', '7', '7');
INSERT INTO `skills` VALUES ('7', 'Build Items', 'Build Items needs description.', '0', 'Total', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('8', 'Build Reactors', 'Allows analysis and manufacture of reactors of a level equal to or below the skill level, and increases the quality of manufactured reactors.', '0', 'Trade', '-1', '-1', '7', '-1', '7', '7', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('9', 'Build Shields', 'Allows analysis and manufacture of shields of a level equal to or below the skill level, and increases the quality of manufactured shields.', '0', 'Trade', '-1', '7', '7', '-1', '-1', '-1', '-1', '-1', '7');
INSERT INTO `skills` VALUES ('10', 'Build Weapons', 'Allows analysis and manufacture of weapons and ammunition of a level equal to or below the skill level, and increases the quality of manufactured items.', '0', 'Trade', '7', '-1', '7', '7', '-1', '7', '7', '-1', '7');
INSERT INTO `skills` VALUES ('11', 'Call Forward', 'Call Forward abilities are used to reclaim skill points.', '0', 'Total', '-1', '1', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('12', 'Cloak', 'Cloaking abilities are used to mask the ship\'s presence, making it difficult or impossible for enemies to locate.', '1', 'Explore', '-1', '-1', '-1', '5', '7', '5', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('13', 'Combat Trance', 'Combat Trance imparts various combat bonuses that automatically take effect when the ship is not moving.', '0', 'Combat', '7', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('14', 'Compulsory Contemplation', 'Compulsory Contemplation abilities confuse a single target.', '1', 'Total', '-1', '-1', '-1', '-1', '1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('15', 'Create Wormhole', 'Create Wormhole abilities provide rapid transport to various locations throughout the galaxy.', '1', 'Explore', '-1', '-1', '-1', '-1', '7', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('16', 'Critical Targeting', 'The Critical Targeting skill passively increases the chance that any attack will critically damage the target.', '0', 'Combat', '7', '5', '5', '5', '-1', '-1', '5', '-1', '-1');
INSERT INTO `skills` VALUES ('17', 'Damage Control', 'The Damage Control increases hull effectiveness.  This increases the amount of damage your hull can sustain.', '0', 'Combat', '7', '-1', '-1', '-1', '-1', '-1', '5', '-1', '-1');
INSERT INTO `skills` VALUES ('18', 'Device Tech', 'Allows use of devices of a level equal to or below the skill level.', '0', 'Total', '8', '9', '8', '9', '9', '9', '8', '9', '8');
INSERT INTO `skills` VALUES ('19', 'Energy Leech', 'This ability drains a portion of an enemy\'s or group of enemies\' energy.  At higher levels, this skill transfers some of that drained energy to the player\'s or a player group\'s energy banks.', '1', 'Combat', '-1', '-1', '-1', '7', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('20', 'Engine Tech', 'Allows use of engines of a level equal to or below the skill level.', '0', 'Total', '8', '8', '8', '8', '8', '8', '9', '9', '9');
INSERT INTO `skills` VALUES ('21', 'Engineering', 'Engineering needs description.', '0', 'Total', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('22', 'Enrage', 'Enrage abilities can be used to anger enemies, forcing them to attack regardless of the situation.', '1', 'Explore', '5', '-1', '-1', '-1', '-1', '-1', '7', '-1', '-1');
INSERT INTO `skills` VALUES ('23', 'Environment Shield', 'Environment Shield abilities are used to protect targets from dangerous environmental effects, such as gravitational shears or radiation.', '1', 'Explore', '-1', '-1', '-1', '-1', '7', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('24', 'Fold Space', 'Fold Space abilities are used to quickly teleport short distances, often to evade danger.', '1', 'Explore', '-1', '-1', '-1', '7', '5', '5', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('25', 'Gravity Link', 'Gravity Link abilities can be used to slow or immobilize enemies.', '1', 'Combat', '7', '5', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('26', 'Hacking', 'Hacking abilities can be used to temporarily disable a target\'s shields, reactor, engine, weapons or devices.', '1', 'Combat', '-1', '-1', '-1', '-1', '-1', '-1', '7', '5', '-1');
INSERT INTO `skills` VALUES ('27', 'Hull Patch', 'Hull Patch abilities are used to repair damaged ship hulls.', '1', 'Combat', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '7', '7');
INSERT INTO `skills` VALUES ('28', 'Item Tech', 'Item Tech needs description.', '0', 'Total', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('29', 'Jenquai Culture', 'Jenquai Culture needs description.', '0', 'Explore', '-1', '-1', '-1', '-1', '-1', '9', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('30', 'Jenquai Lore', 'Jenquai Lore needs description.', '0', 'Total', '-1', '-1', '-1', '-1', '-1', '9', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('31', 'Jumpstart', 'The Jumpstart skill is used to resuscitate incapacitated players.', '1', 'Explore', '-1', '7', '-1', '-1', '7', '-1', '-1', '7', '-1');
INSERT INTO `skills` VALUES ('32', 'Maelstrom Resonance', 'The Maelstrom Resonance skill enables a V\'rix to surround its groupmates with a resonance similar to the makeup of the Maelstrom reality.  This results in protection from Human technologies.', '1', 'Explore', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('33', 'Menace', 'Menace abilities can be used to frighten enemies, causing them to flee.', '1', 'Explore', '-1', '7', '5', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('34', 'Missile Weapon', 'Allows use of missile weapons of a level equal to or below the skill level, and increases damage with missile weapons by +25% per level.', '0', 'Combat', '8', '8', '8', '8', '-1', '-1', '9', '9', '9');
INSERT INTO `skills` VALUES ('35', 'Navigate', 'The Navigate skill imparts various bonuses that aid travel.', '0', 'Explore', '-1', '-1', '-1', '-1', '7', '-1', '5', '7', '5');
INSERT INTO `skills` VALUES ('36', 'Negotiate', 'The Negotiate skill allows negotiation of reduced prices or increased profits when interacting with NPC vendors.', '0', 'Trade', '-1', '-1', '5', '-1', '-1', '5', '5', '5', '7');
INSERT INTO `skills` VALUES ('37', 'Power Down', 'Power Down abilities are used to fool enemies by making the ship appear incapacitated, often causing enemies to break off attacks.', '1', 'Combat', '-1', '7', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('38', 'Progen Culture', 'Progen Culture needs description.', '0', 'Explore', '8', '7', '5', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('39', 'Progen Lore', 'Progen Lore needs description.', '0', 'Total', '8', '7', '5', '-1', '-1', '-1', '-1', '-1', '-1'), ('40', 'Projectile Weapon', 'Allows use of projectile weapons of a level equal to or below the skill level, and increases damage with projectile weapons by +25% per level.', '0', 'Combat', '9', '9', '9', '8', '8', '8', '8', '-1', '-1'), ('41', 'Prospect', 'The Prospect skill allows retrieval of valuable resources from objects such as asteroids, gas clouds, and hulks.  This skill is activated using a action button that will appear when a prospectable object is targeted.', '0', 'Explore', '-1', '7', '-1', '-1', '7', '-1', '-1', '7', '-1'), ('42', 'Psionic Shield', 'Psionic Shield abilities create a temporary shield around any ship that absorbs damage and improves resistance to special attacks.', '1', 'Combat', '-1', '-1', '-1', '7', '-1', '-1', '-1', '-1', '-1'), ('43', 'Reactor Optimization', 'The Reactor Optimization ability allows players to temporarily increase their Reactor Capacity and Reactor Regeneration Rate.', '1', 'Combat', '-1', '-1', '-1', '-1', '-1', '7', '-1', '-1', '-1'), ('44', 'Rally', 'Rally abilities are used to provide various combat bonuses to all group members simultaneously.', '1', 'Combat', '-1', '-1', '-1', '-1', '-1', '-1', '7', '-1', '-1'), ('45', 'Reactor Tech', 'Allows use of reactors of a level equal to or below the skill level.', '0', 'Total', '9', '8', '9', '9', '9', '9', '8', '8', '8'), ('46', 'Recharge Shields', 'Recharge Shields abilities are used to quickly recharge shield energy levels.', '1', 'Combat', '-1', '-1', '7', '-1', '-1', '7', '-1', '-1', '7'), ('47', 'Repair Equipment', 'The Repair Equipment skill can be used to repair damaged or destroyed equipment, restoring normal operation.', '1', 'Trade', '7', '-1', '-1', '7', '-1', '-1', '7', '-1', '-1'), ('48', 'Repulsor Field', 'Repulsor Field abilities generate feedback that returns energy damage to the original source of incoming damage. At higher levels the damaged returned increases.  The affected damage types for all levels are: Chemical, EMP, Energy, Explosive, Impact, Plasma', '1', 'Explore', '-1', '7', '-1', '-1', '-1', '-1', '-1', '-1', '-1'), ('49', 'Scan', 'The Scan skill grants passive bonuses that increase object detection distance and allow targeting of cloaked objects.', '0', 'Explore', '-1', '5', '-1', '7', '7', '5', '-1', '5', '-1'), ('50', 'Self Destruct', 'Self Destruct abilities temporarily incapacitate the ship but cause tremendous damage to all surrounding enemies.  When self destruct is utilized, the ship loses all shield and reactor energy, and is temporarily unable to perform any action.', '1', 'Combat', '7', '-1', '-1', '-1', '-1', '5', '-1', '-1', '-1'), ('51', 'Shield Charging', 'The Shield Charging ability allows players to temporarily increase their Shield Capacity, Shield Regeneration Rate and Damage Resistances.', '1', 'Combat', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '7'), ('52', 'Shield Inversion', 'Shield Inversion abilities allow the shield to be used as a short-range weapon, inflicting heavy damage but depleting shield energy.', '1', 'Combat', '7', '-1', '7', '-1', '-1', '-1', '-1', '-1', '-1'), ('53', 'Shield Leech', 'This ability drains a portion of an enemy\'s or group of enemies\' shields.  At higher levels, this skill transfers some of those drained shields to the player\'s or a player group\'s energy banks.', '1', 'Explore', '-1', '-1', '-1', '-1', '7', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('54', 'Shield Sap', 'Shield Sap abilities drain a portion of a target\'s or group of targets shields. At higher levels a fraction of the drained shield energy is transferred to the shields of the skill user or the skill user\'s group.', '1', 'Combat', '7', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
INSERT INTO `skills` VALUES ('55', 'Shield Tech', 'Allows use of shields of a level equal to or below the skill level.', '0', 'Total', '9', '9', '9', '8', '8', '8', '9', '8', '9');
INSERT INTO `skills` VALUES ('56', 'Summon', 'Summon abilities are used to teleport friends or enemies to the current location.', '1', 'Combat', '-1', '-1', '-1', '7', '-1', '-1', '-1', '-1', '-1');
