INSERT INTO `skills` VALUES ('58', 'Quantum Flux', 'Quantum Flux is a V\'rix skill that destabilizes an enemy\'s ship on the quantum level.  This results in partial implosion and massive damage.', '1', 'Combat', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1', '-1');
