INSERT INTO `starbase_npcs` VALUES ('243', 'Shang Li', 'Chun', '6', '2', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>Yo Ho Ho and a Bottle of Rum!</Text>\r\n	<Branch Node=\"2\">More</Branch>\r\n	<Branch Node=\"3\">Huh?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Watch yer step, the blood needs cleaned up! If you\'ve come for knife fights ye will find them near the back. If ye here for the beer then turn right around. Only the best Rum is served here!</Text>\r\n	<Branch Node=\"5\">I\'m here for the knife fights!</Branch>\r\n	<Branch Node=\"4\">I have some rum.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>Have it your own way scoundrel! Be gone with yer self!</Text>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n	<Text>Thanks for your business! It always helps to drink a little rum... makes the pain a little less!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n	<Text>If yer blood spills. ye clean it up yourself! </Text>\r\n</Tree>\r\n', '122', '0');
INSERT INTO `starbase_npcs` VALUES ('244', 'Julius', 'Ortega', '11', '2', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>/salute @race! You want the most powerful weapons around!? Take a look at what I have for you here!</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '123', '0');
INSERT INTO `starbase_npcs` VALUES ('245', 'Ivanna', '', '6', '2', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>/salute Hello @race! Take a look at my equipment! You won\'t find this stuff anywhere else in the galaxy!</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '123', '1');
INSERT INTO `starbase_npcs` VALUES ('246', 'Leila', 'Endora', '10', '2', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name! I have the perfect components for all your needs. Take a look at my stock.</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '123', '2');
INSERT INTO `starbase_npcs` VALUES ('247', 'Mark', 'Cyrus', '4', '8', 'Components npc', '<Tree Node=\"1\">\r\n	<Text>Greetings stranger.   I\'ll be selling Experimental Laser Lenses for a mission one day, but I got nothing for you now.  See ya later.</Text>\r\n	<Branch Node=\"2\">Show me your wares</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Here ya go</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n', '136', '0');
INSERT INTO `starbase_npcs` VALUES ('248', 'Amyli', 'Hamston', '1', '8', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. How about some amunition ?</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '136', '1');
INSERT INTO `starbase_npcs` VALUES ('249', 'Daniel', 'Yonda', '3', '8', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. Take a look at the new engines I just got in!</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '136', '2');
INSERT INTO `starbase_npcs` VALUES ('250', 'Draegul', 'McCrocker', '10', '8', 'trade goods', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. Take a look at the Trade items I have.</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '136', '3');
INSERT INTO `starbase_npcs` VALUES ('251', 'Vel', 'Ohla', '6', '8', 'comp L4', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name.   Level 4 parts is what I got!</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '136', '4');
INSERT INTO `starbase_npcs` VALUES ('252', 'Angelique', 'DeSaro', '11', '8', 'comp L5', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. I have all the level 5 components you desire.</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '136', '5');
INSERT INTO `starbase_npcs` VALUES ('253', 'Neva', 'Anaso', '5', '8', 'comps L6', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. Get your level 6 components here and only here.</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '136', '6');
INSERT INTO `starbase_npcs` VALUES ('254', 'Theodoric', 'Cassel', '8', '15', 'Enter Description', 'Enter Talk tree Handler', '125', '0'), ('255', 'Laurel', 'Provum', '0', '15', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>A Sabine? One of Vinda\'s sheep? I don\'t have time for you.</Text>\r\n	<Branch Node=\"2\">What does THAT mean?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/crazy Nothing. Forget it. Forget I said anything. Just leave me alone, and forget we met. I will.</Text>\r\n	<Branch Node=\"3\">Are you a Versatile? Specialist? Reclaimer?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/angry I\'m NO Reclaimer, Sabine! Why would you say that, anyway? I\'m NO Reclaimer, do you hear me?</Text>\r\n	<Branch Node=\"4\">What ARE you, then?</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n	<Text>What I am doesn\'t concern you, sheep! I\'m no Reclaimer! Do you smell death? I don\'t. You\'re asking the WRONG questions, Sabine. There\'s better questions, if you\'d look around. Like what\'s the deal with the big lummox in the main hall? He\'s got a secret. Did you know that? In fact, he\'s got all kinds of secrets. Ask him what HE is. Ask Vinda about these warriors here. Why are they so different from the rest? What KIND of Centuriata ARE they? All kinds of questions to ask, Sabine. See that you ask the right ones. And meanwhile, leave me alone.</Text>\r\n	<Branch Node=\"5\">What about my mission from Cassel?</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n	<Text>I don\'t have time to deal with that. Leave me alone!</Text>\r\n	<Trade>0</Trade>\r\n</Tree>\r\n', '125', '1'), ('256', 'Andronicus', 'Tyr', '11', '15', 'Enter Description', '<Tree Node=\"1\">\r\n     <Text> Can I assist?\r\n</Text>\r\n                 <Branch Node=\"2\">I have some questions.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n     <Text>Certainly! I\'ll answer what I can, as the Harmony wills it.</Text>\r\n                 <Branch Node=\"3\">Tell me about yourself.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n     <Text>About myself, friend? What do you mean?</Text>\r\n                 <Branch Node=\"4\">Did you fight in the Cygni War?</Branch>\r\n                 <Branch Node=\"5\">What\'s this Harmony you always mention? </Branch>\r\n                 <Branch Node=\"6\">What do you do here?</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n     <Text>What!? Why would you ask about THAT? Did someone put you up to it? They know what I believe... that wasn\'t ME... not the same SOUL! It would be better, Carroll, if you didn\'t ask me about this again. No more bloody questions... Not about THAT. ~Conversation ends~ </Text>\r\n</Text>\r\n<Tree Node=\"5\">\r\n     <Text> N-nothing, really. A turn of phrase, nothing more. No matter what others may say... Leave it at that, friend. It\'s better for us both, I think. ~Conversation ends~</Text>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n     <Text> Myself - and my contingent - we\'re here to protect Arx Spartoi. We\'re trusted by the Magisters Magna to keep this place safe. And I try to guide whoever I can. I try to be helpful, as most warriors can\'t. To atone, you might say. Mm. Listen to me. I do what I can, Carroll, and that\'s enough. And I represent the warriors - not Kahn\'s warriors, but those in Sabine employ. I speak for them to the Magisters Magna. </Text>\r\n                 <Branch Node=\"7\">Thank you. I should go.</Branch>\r\n</Tree>\r\n<Tree Node=\"7\">\r\n     <Text>I will also be teaching the Critical Targeting skill</Text>\r\n</Tree>\r\n                 \r\n', '125', '2'), ('257', 'Ulley', 'Nirom', '1', '15', 'Progen', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, is what weapons do you want to buy from me?</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '126', '0');
INSERT INTO `starbase_npcs` VALUES ('258', 'Petra', 'Blanca', '8', '15', 'Progen', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, I have devices, engines, reactors and shields for sale.</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '126', '1');
INSERT INTO `starbase_npcs` VALUES ('260', 'Ulpia', 'Adilla', '3', '15', 'Progen, Trade Goods vender.', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, do you want to see what Trade Goods are on offer?</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '126', '2');
INSERT INTO `starbase_npcs` VALUES ('261', 'Truffeni', 'Petilius', '10', '15', 'Progen, Level 2 components vender.', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, which level 2 components do you want to buy?</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '126', '3');
INSERT INTO `starbase_npcs` VALUES ('262', 'Carcellus', 'Volusensus', '12', '15', 'Progen, Level 3 components vender.', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, which level 3 components do you want to buy?</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '126', '4');
INSERT INTO `starbase_npcs` VALUES ('263', 'Verica', 'Aulus', '1', '15', 'Progen, Level 4 components vender.\r\n\r\nERROR:  Missing NPC - not showing at the location.  Location 1 clashes with Weapon Vender Ulley Nirom', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, which level 4 components do you want to buy?</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '126', '5');
INSERT INTO `starbase_npcs` VALUES ('264', 'Calliope', 'Gans', '3', '15', 'Should sell to Sentinels (Call Forward Mission):\r\nSterile Petri Dish\r\nSterile Beaker\r\nSterile Reagent Bottle\r\nSterile Graduated Beaker\r\nSterile Test Tube', '<Tree Node=\"1\">\r\n     <Text>/happy1I remember you... Good conversation. Enigmatic. Enigmatic is good.</Text>\r\n                 <Branch Node=\"2\">I have some questions... </Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n     <Text>Sure. Okay. Questions are interesting.</Text>\r\n                 <Branch Node=\"3\">What do you know about Andronicus Tyr?</Branch>\r\n                 <Branch Node=\"5\">What are you doing here?</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n     <Text>Tyr? The pious pill-popper himself? Okay, see... HE is weird. People call ME a freak, but... he freaks ME out.</Text>\r\n                 <Branch Node=\"4\">Why is that?</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n                 <Text>First of all, he\'s got all these weird people coming in and out of here at the strangest hours... and you know, it\'s not like they\'re hard to miss. It\'s Terrans and Jenquai, mostly, but FREAKY. Weird religious types, you know? And then there\'s the pills. See, he pops a LOT of pills. And it\'s not THAT hard to figure out, you know? Something\'s bothering him... his past, delusions, perverse recurring thoughts, who knows. But he FREAKS me out. I mean, don\'t get me wrong. I like the guy. Weirdness is a good thing. Weird people are interesting. Like puzzles. But better appreciated from afar, you know?</Text>\r\n     <Text>/give Thanks for trading!</Text>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n     <Text>Long story. Long, WEIRD story. So, it started when Vinda sends these warrior-guys to drag me back to Endriago, all the way from Aragoth. I mean, I\'m in the middle of this weapons research thing, and they just, like, KILL me. Next thing I know. I\'m here. I\'m reiterated, I\'m promoted to Magister, and I\'m supposed to figure out how to get Progen ships into the Maelstroms. Sleep... out of the question. SO weird. Okay, so maybe it wasn\'t that long of a story. But weird, right? You\'ve got to admit it\'s weird.</Text>\r\n                 <Branch Node=\"6\">Interesting. But I should go.</Branch>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n     <Text>/happy1I will also be teaching the Device Building skills once i have been approved for it..</Text>\r\n</Tree>', '127', '0');
INSERT INTO `starbase_npcs` VALUES ('265', 'Reclaimer', 'Ort', '10', '15', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>Manes ... dont underestaminate theyr value @race</Text>\r\n	<Branch Node=\"2\">Sorry what are manes ?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text></Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n', '127', '1');
INSERT INTO `starbase_npcs` VALUES ('266', 'Cestum', 'Talus', '13', '15', 'Enter Description', '<Tree Node=\"1\">\r\n     <Text>/happy1 I get to teach shield building</Text>\r\n                 <Branch Node=\"2\">Has Tienbau ok\'ed this?</Branch>\r\n                 <Branch Node=\"3\">You Sure!</Branch>\r\n                 <Branch Node=\"4\">Trade!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n     <Text>/crazy No, but it will be soon</Text>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n     <Text>/bow Woot Lets do it!!</Text>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n                 <Trade>1</Trade>\r\n     <Text>/give Thanks for trading!</Text>\r\n</Tree>\r\n', '127', '2');
INSERT INTO `starbase_npcs` VALUES ('267', 'Anusha', 'Dayakara', '10', '8', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text> /sigh  Who are you with?  Conservationists?  Hunters?  Glenn Commission?</Text>\r\n	<Branch Node=\"2\">Actually, I\'m not \'with\' anyone. </Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Wait. You\'re not one of those students, are you? The ones I sent to lobby the Glenn Commission?</Text>\r\n	<Branch Node=\"3\">No. Definitely not.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>Good. They came to me, wailing about the Dzurai and the Nommos, yearning for an earlier age of protests, demonstrations... Nobody protests anymore. There aren\'t demonstrations in space. You have a problem, you pollute a planet, you move on to the next. They didn\'t KNOW what they wanted. Ended up squandering my money in Friendship 7. Hand me that datacube, would you?</Text>\r\n	<Branch Node=\"4\">Alright. But maybe I could help, somehow?</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n	<Text>I doubt it. Look, I certainly don\'t mean to be rude - Jenquai conscience you know, they drill the politeness into you from birth, but every minute I lose is one less minute of data we\'ll have on this system. And with all the hunting, and the tour ships... this system won\'t be pristine for long. Just more tame space.</Text>\r\n	<Branch Node=\"5\">I understand. I should go. </Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n	<Text>Listen. You MAY be able to help me, eventually. I study Grissom, mostly. The gas giant. Right now, you\'d be eaten alive out there. I can\'t send you, and I won\'t. But when you\'re better able to take care of yourself... if you\'re really interested, come and see me again.</Text>\r\n</Tree>\r\n', '135', '0');
INSERT INTO `starbase_npcs` VALUES ('268', 'Josher', '', '9', '8', 'Enter Description', '<Tree Node=\"1\">\r\n     <Text>Heyhowdy there, friend. Still slumming on Orsini? Say, stop me if you\'ve heard this one--a Progen, a Terran, and a Jenquai are riding in a transport when...</Text>\r\n                 <Branch Node=\"2\">STOP! I\'ve heard it.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n     <Text>I\'ve got a million of \'em. What can I do for you? </Text>\r\n                 <Branch Node=\"3\">Give me a mission.</Branch>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n     <Text> And I sure could use some help, but I gotta be honest, you\'re too green around the gills for what I need done. You need to knock around the universe some more, then come on back to see me.</Text>\r\n</Tree>\r\n\r\n\r\nUpon reaching level 65, Josher gives out the following mission:\r\n\r\n\r\n\r\n<Tree Node=\"4\">\r\n     <Text> Heyhowdy there, friend. Still slumming on Orsini? Say, stop me if you\'ve heard this one -- a Progen, a Terran and a Jenquai are riding in a transport when...</Text>\r\n                  <Branch Node=\"5\">Josher, I would like to have a mission.</Branch>\r\n</Tree>\r\n<Tree Node=\"5\">\r\n     <Text>Hooboy. I\'m a world of hurtin\' and I could use the help. That scumbag, Lucius Campano, the guy who runs the scinnie races, is gonna ruin me. </Text>\r\n                  <Branch Node=\"6\">Scinnies? </Branch>\r\n</Tree>\r\n<Tree Node=\"6\">\r\n     <Text> Scaracens. Big ole space creatures that live around here. We breed\'em and race\'em. Ta\'be brief, I love to bet on the scinnies, but my luck flebs, it purely flebs. I\'m in deep to Campano. Owe him more credits than I\'ll ever see in this lifetime. Campano\'s threatening to expose me. Like I told you, I\'m the purser here. I handle money and goods. People trust me. If Campano puts out the word I\'m a gambler, my job is history and I may as well space myself. Thing is, Campano says he\'ll forgive my debt if I do something dangerous for him, but it takes a good ship and I got no ship. All I ever had was a tramphauler my papa left me. It\'s long gone. My Freespacer days are over. Do this for me and I\'ll make it worth your while.</Text>\r\n                  <Branch Node=\"7\">A reward? What are you offering? </Branch>\r\n</Tree>\r\n<Tree Node=\"7\">\r\n     <Text> I pick up great deals around here. I\'ll give you a GETCo speed booster device. You\'ll have to talk to Campano to find out what he wants done. He\'s at the Scaracen raceway office. Go to the Friendship 7 station, then follow the Friendship 4 Nav to the raceway. I can\'t thank you enough. Best\'a luck.</Text>\r\n</Tree>\r\n\r\n\r\nFly to Orsini Mining Platform \r\n\r\n\r\n\r\n\r\n<Tree Node=\"8\">\r\n     <Text>Hooboyhowdy, it\'s good to see you again! Am I clear with Campano? No more debt? </Text>\r\n                   <Branch Node=\"9\">He says you\'re clear, but Campano\'s a nasty piece of business. What is Xenocafenal?</Branch>\r\n</Tree>\r\n<Tree Node=\"9\">\r\n     <Text> What?! Why that flebbing yurk! Xenocafenal\'s a drug that makes the scinnies fly faster for longer. He\'s using it to rig the races. I owe you twice over for that piece of news. I won\'t hold you up any longer. Lemme get that device loaded up. It\'s in your hold and ready to go. And thanks again. You\'ve saved me from being a ruined man. Say, did you hear the one about...</Text>\r\n                   <Branch Node=\"9\">Goodbye, Josher! </Branch>\r\n', '135', '1');
INSERT INTO `starbase_npcs` VALUES ('269', 'Lancearate', 'Fortunatis', '0', '3', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>Hail @name!</Text>\r\n	<Branch Node=\"2\">Hail.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Excuse me. I have no assignments, currently, for you.</Text>\r\n	<Trade>0</Trade>\r\n</Tree>\r\n', '129', '0');
INSERT INTO `starbase_npcs` VALUES ('270', 'Praefect Hadrin', 'Gurk', '4', '3', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>Hail Centurian!</Text>\r\n	<Branch Node=\"2\">Hail!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Pardon me, I\'m busy.</Text>\r\n	<Trade>0</Trade>\r\n</Tree>\r\n', '129', '1');
INSERT INTO `starbase_npcs` VALUES ('271', 'Markus', 'Kahn', '9', '3', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>I\'m in the middle of something.</Text>\r\n	<Branch Node=\"2\">ok?</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>Go away.</Text>\r\n	<Trade>0</Trade>\r\n</Tree>\r\n', '129', '2');
INSERT INTO `starbase_npcs` VALUES ('272', 'Zaneda', 'Lyro', '8', '3', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, how about s</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '130', '0');
INSERT INTO `starbase_npcs` VALUES ('273', 'Ormos', 'Mentis', '1', '3', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, how about s</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '130', '1');
INSERT INTO `starbase_npcs` VALUES ('274', 'Lucuis', 'Valgus', '6', '3', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>Hail @profession.\r\n\r\nHurry up, I haven\'t all day, I provide many level 5 components.</Text>\r\n	<Branch Node=\"3\">Hail Lucuis, my name is @name.</Branch>\r\n	<Branch Node=\"2\">My mistake, I wanted to trade with someone else.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>What!? \r\nBegone Curr!</Text>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/salue\r\nLet me show you what I can offer you.</Text>\r\n	<Trade>0</Trade>\r\n	<Branch Node=\"4\">This is all I require, Good bye.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n	<Text>Happy hunting, @name of the @race @profession.</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n', '130', '2'), ('275', 'Ceanatis', 'Plotius', '2', '3', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>Hail @profession.\r\n\r\nHurry up, I haven\'t all day, I provide many level 2 components.</Text>\r\n	<Branch Node=\"3\">Hail Ceanatis, my name is @name.</Branch>\r\n	<Branch Node=\"2\">My mistake, I wanted to trade with someone else.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>What!? \r\nBegone Curr!</Text>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/salue\r\nLet me show you what I can offer you.</Text>\r\n	<Trade>0</Trade>\r\n	<Branch Node=\"4\">This is all I require, Good bye.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n	<Text>Happy hunting, @name of the @race @profession.</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n', '130', '3');
INSERT INTO `starbase_npcs` VALUES ('276', 'Celia', 'Lusius', '4', '3', 'Enter Description', '<Tree Node=\"1\">\r\n	<Text>Hail @profession.\r\n\r\nHurry up, I haven\'t all day, I provide many level 3 components.</Text>\r\n	<Branch Node=\"3\">Hail Celia, my name is @name.</Branch>\r\n	<Branch Node=\"2\">My mistake, I wanted to trade with someone else.</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>What!? \r\nBegone Curr!</Text>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/salue\r\nLet me show you what I can offer you.</Text>\r\n	<Trade>0</Trade>\r\n	<Branch Node=\"4\">This is all I require, Good bye.</Branch>\r\n</Tree>\r\n<Tree Node=\"4\">\r\n	<Text>Happy hunting, @name of the @race @profession.</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n', '130', '4');
