INSERT INTO `starbase_npcs` VALUES ('608', 'Tyrian', 'Ikaruga', '6', '18', 'Enter Discription', 'talktree', '264', '2'), ('609', 'Nodens', 'Ictus', '2', '5', 'Enter Discription', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, would you be interested in some weapons?</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '265', '0');
INSERT INTO `starbase_npcs` VALUES ('610', 'Chip', 'Crispin', '5', '11', 'Enter Discription', '<Tree Node=\"1\">\r\n	<Text>/salute Welcome @name. The @race race is always welcome at my booth, would you be interested in some equipment?</Text>\r\n	<Branch Node=\"2\">Trade!</Branch>\r\n	<Branch Node=\"3\">No Thanks!</Branch>\r\n</Tree>\r\n<Tree Node=\"2\">\r\n	<Text>/give Thanks, and come back soon!</Text>\r\n	<Trade>1</Trade>\r\n</Tree>\r\n<Tree Node=\"3\">\r\n	<Text>/bow Okay then, I will be here when you need my services.</Text>\r\n</Tree>\r\n', '265', '1');
